insert into public.articles (id, slug, title, description, category, body, citations, author_name, author_bio, reading_time_minutes, published_on, status)
values
  ('window-functions-sql', 'window-functions-sql', 'Window functions: a diferença entre RANK, DENSE_RANK e ROW_NUMBER', 'Exemplos comentados para escolher a função de janela certa em relatórios de ranking e deduplicação de registros.', 'SQL', array['As três funções de janela mais confundidas em SQL fazem quase a mesma coisa — atribuir uma posição a cada linha dentro de um grupo — mas se comportam de forma diferente quando existem empates. Escolher a errada gera relatórios sutilmente incorretos que passam despercebidos até alguém somar os números.', '## A diferença na prática', 'ROW_NUMBER() sempre atribui um número único e sequencial, mesmo quando os valores usados no ORDER BY são idênticos — em caso de empate, a ordem entre eles é arbitrária (a menos que você desempate explicitamente no ORDER BY). RANK() dá a mesma posição para valores empatados, mas pula números depois do empate: dois primeiros lugares empatados fazem o próximo ser o terceiro, não o segundo. DENSE_RANK() também empata, mas não deixa buracos na sequência: depois de dois primeiros lugares, o próximo é o segundo.', '```sql
insert into public.news (id, slug, title, summary, relevance, published_on, verified_on, verification, verification_notes, categories, tags, source_name, source_url, image_url, featured, related, status)
values
  ('openai-lanca-chatgpt', 'openai-lanca-chatgpt', 'OpenAI lança o ChatGPT ao público', 'A OpenAI publicou um post de blog anunciando o ChatGPT como uma "pesquisa de prévia" (research preview), um modelo conversacional derivado da família GPT-3.5. O lançamento, feito sem grande evento de marketing, ultrapassou 1 milhão de usuários em cinco dias.', 'Marco que popularizou IA generativa em escala global e mudou a forma como profissionais de dados passaram a usar assistentes de linguagem no dia a dia de trabalho.', '2022-11-30'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Machine Learning']::text[], array['ChatGPT', 'OpenAI', 'IA Generativa', 'GPT-3.5']::text[], 'OpenAI (blog oficial)', 'https://openai.com/blog/chatgpt', null, true, '{}'::jsonb, 'published'),
  ('databricks-open-source-delta-lake-2', 'databricks-open-source-delta-lake-2', 'Databricks abre o código completo do Delta Lake 2.0', 'A Databricks anunciou que todos os recursos do Delta Lake, incluindo funcionalidades antes restritas à sua plataforma paga, passaram a ser 100% open source sob a Linux Foundation. A empresa afirmou que o formato já era usado por milhares de organizações processando grandes volumes de dados diariamente.', 'Reduz o lock-in em torno do formato de tabelas do lakehouse e acelera a adoção de arquiteturas abertas de dados por equipes de engenharia.', '2022-06-30'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Open Source']::text[], array['Databricks', 'Delta Lake', 'Lakehouse', 'Linux Foundation']::text[], 'Databricks (blog oficial)', 'https://www.databricks.com/blog/2022/06/30/open-sourcing-all-of-delta-lake.html', null, false, '{}'::jsonb, 'published'),
  ('snowflake-anuncia-unistore', 'snowflake-anuncia-unistore', 'Snowflake anuncia o Unistore para unir dados transacionais e analíticos', 'No Snowflake Summit 2022, a empresa anunciou o Unistore, um novo workload baseado em "hybrid tables" que combina operações transacionais rápidas com o desempenho analítico do Data Cloud. Clientes como Adobe e Novartis já testavam o recurso em prévia privada.', 'Sinaliza a tendência de plataformas de dados tentarem eliminar a separação clássica entre bancos transacionais (OLTP) e analíticos (OLAP).', '2022-06-14'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Data Platforms']::text[], array['Snowflake', 'Unistore', 'Hybrid Tables', 'HTAP']::text[], 'Snowflake (comunicado oficial)', 'https://www.snowflake.com/en/news/press-releases/snowflake-launches-new-unistore-workload-to-drive-next-phase-of-innovation-with-transactional-and-analytical-data-together-in-the-data-cloud-2/', null, false, '{}'::jsonb, 'published'),
  ('snowflake-suporte-apache-iceberg', 'snowflake-suporte-apache-iceberg', 'Snowflake revela suporte nativo a tabelas Apache Iceberg', 'Ao encerrar o Snowflake Summit 2022, a empresa confirmou que "Iceberg Tables" estava em desenvolvimento, permitindo que dados armazenados em formato aberto e fora do Snowflake fossem acessados diretamente pelo Data Cloud. Foi um dos primeiros movimentos claros da Snowflake em direção à interoperabilidade com formatos abertos de lakehouse.', 'Mostra o início da corrida das grandes plataformas de dados para suportar o Apache Iceberg como padrão de tabela aberto, tema central da engenharia de dados nos anos seguintes.', '2022-06-22'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Open Source']::text[], array['Snowflake', 'Apache Iceberg', 'Lakehouse', 'Formato Aberto']::text[], 'Snowflake (comunicado oficial)', 'https://www.snowflake.com/en/news/press-releases/snowflake-concludes-its-largest-ever-global-user-conference-with-new-innovations-to-drive-application-development-and-increased-collaboration-in-the-data-cloud/', null, false, '{}'::jsonb, 'published'),
  ('google-cloud-lanca-biglake', 'google-cloud-lanca-biglake', 'Google Cloud lança o BigLake para unificar data warehouse e data lake', 'No Data Cloud Summit, o Google Cloud anunciou o BigLake, um mecanismo de armazenamento que estende o BigQuery para dados em data lakes multi-nuvem sem exigir duplicação de dados. O recurso, em prévia, também previa suporte a formatos abertos como Apache Iceberg e integração com o Dataplex para governança.', 'Representa a aposta do Google na arquitetura lakehouse, permitindo que equipes de dados analisem dados de diferentes nuvens com um único ponto de controle de acesso.', '2022-04-05'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Cloud', 'Data Engineering']::text[], array['Google Cloud', 'BigLake', 'BigQuery', 'Data Lake']::text[], 'TechCrunch', 'https://techcrunch.com/2022/04/05/google-cloud-launches-biglake-a-new-cross-platform-data-storage-engine/', null, false, '{}'::jsonb, 'published'),
  ('aws-reinvent-2022-zero-etl', 'aws-reinvent-2022-zero-etl', 'AWS anuncia integração Zero-ETL entre Aurora e Redshift no re:Invent 2022', 'A AWS detalhou os principais anúncios de analytics do re:Invent 2022, incluindo a integração Zero-ETL entre Aurora e Redshift, ingestão em streaming via Kinesis e Kafka, Multi-AZ para o Redshift e o novo Amazon DataZone para catalogação e governança de dados.', 'Reduz a complexidade de pipelines de ETL tradicionais e mostra a tendência de integração nativa entre bancos operacionais e data warehouses na nuvem.', '2022-12-19'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Cloud', 'Data Engineering']::text[], array['AWS', 'Redshift', 're:Invent', 'Zero-ETL']::text[], 'AWS (blog oficial)', 'https://aws.amazon.com/blogs/big-data/top-analytics-announcements-of-aws-reinvent-2022/', null, false, '{}'::jsonb, 'published'),
  ('postgresql-15-lancado', 'postgresql-15-lancado', 'PostgreSQL 15 é lançado com o comando MERGE e melhorias de replicação lógica', 'O PostgreSQL 15 foi lançado trazendo o comando SQL MERGE, publicação seletiva de colunas e filtros de linha em replicação lógica, além de suporte à compressão Zstandard. Testes mostraram ganhos de desempenho em ordenação de até 400% dependendo do tipo de dado.', 'O MERGE facilita operações de upsert diretamente em SQL, algo já comum em outros bancos, tornando o PostgreSQL ainda mais competitivo para cargas analíticas e transacionais.', '2022-10-13'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Open Source']::text[], array['PostgreSQL', 'SQL', 'MERGE', 'Banco de Dados Relacional']::text[], 'PostgreSQL Global Development Group (site oficial)', 'https://www.postgresql.org/about/news/postgresql-15-released-2526/', null, false, '{"trackSlugs":["sql"],"articleIds":["ctes-recursivas-sql"]}'::jsonb, 'published'),
  ('redis-7-lancado', 'redis-7-lancado', 'Redis 7.0 chega com Redis Functions e Sharded Pub/Sub', 'Após quase um ano de desenvolvimento e três release candidates, o Redis 7.0 tornou-se disponível de forma geral com quase 50 novos comandos, incluindo Redis Functions, ACLv2 e Sharded Pub/Sub. O lançamento focou em melhorias de desempenho em memória, rede e armazenamento.', 'Redis é uma das camadas de cache e mensageria mais usadas em arquiteturas de dados modernas, e essas mudanças afetam diretamente como aplicações escalam operações em tempo real.', '2022-04-27'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Open Source']::text[], array['Redis', 'NoSQL', 'Cache', 'Redis Functions']::text[], 'Redis (blog oficial)', 'https://redis.io/blog/redis-7-generally-available/', null, false, '{}'::jsonb, 'published'),
  ('dbt-labs-serie-d', 'dbt-labs-serie-d', 'dbt Labs capta US$ 222 milhões em rodada Série D', 'A dbt Labs anunciou uma rodada Série D de US$ 222 milhões liderada pela Altimeter, avaliando a empresa em US$ 4,2 bilhões, com participação estratégica de Databricks e Snowflake. O investimento reforçou a posição do dbt como ferramenta central da chamada "modern data stack".', 'Consolidou o papel do dbt e da disciplina de "analytics engineering" como peça-chave entre a ingestão de dados brutos e o consumo analítico final.', '2022-02-24'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Mercado', 'Data Engineering']::text[], array['dbt Labs', 'Analytics Engineering', 'Funding', 'Modern Data Stack']::text[], 'dbt Labs (blog oficial)', 'https://www.getdbt.com/blog/dbt-labs-raises-222m-in-series-d-funding-at-4-2b-valuation-led-by-altimeter-with-participation-from-databricks-and-snowflake', null, false, '{}'::jsonb, 'published'),
  ('nvidia-anuncia-hopper-h100', 'nvidia-anuncia-hopper-h100', 'Nvidia anuncia a arquitetura Hopper e a GPU H100', 'Na GTC 2022, a Nvidia revelou a arquitetura Hopper e a GPU H100, com um novo "Transformer Engine" voltado à aceleração de modelos de linguagem e sistemas de recomendação. A empresa também apresentou o superchip Grace CPU, com disponibilidade da H100 prevista para o terceiro trimestre de 2022.', 'A H100 se tornaria a GPU de referência para treinar grandes modelos de IA, sendo peça central da infraestrutura por trás do boom de IA generativa que se seguiria.', '2022-03-22'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Infraestrutura', 'Machine Learning']::text[], array['Nvidia', 'GPU', 'Hopper', 'H100']::text[], 'Nvidia (comunicado oficial)', 'https://nvidianews.nvidia.com/news/nvidia-announces-hopper-architecture-the-next-generation-of-accelerated-computing', null, false, '{}'::jsonb, 'published'),
  ('duckdb-060-lancado', 'duckdb-060-lancado', 'DuckDB 0.6.0 traz leitor CSV paralelo e melhorias de armazenamento', 'A versão 0.6.0 do DuckDB, apelidada "Oxyura", trouxe um leitor de CSV paralelo experimental, carregamento paralelo de dados em tabelas e melhorias no gerenciamento de memória para criação de índices. O lançamento reforçou o foco do projeto em desempenho analítico local.', 'DuckDB ganhava tração como banco analítico "in-process" leve, muito usado por cientistas e engenheiros de dados para análises locais sem a necessidade de um cluster.', '2022-11-14'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Open Source']::text[], array['DuckDB', 'OLAP', 'Analytics Engineering', 'Banco In-Process']::text[], 'DuckDB (blog oficial)', 'https://duckdb.org/2022/11/14/announcing-duckdb-060', null, false, '{}'::jsonb, 'published'),
  ('bc-vazamento-chaves-pix-2022', 'bc-vazamento-chaves-pix-2022', 'Banco Central comunica vazamento de dados de 160,1 mil chaves Pix', 'O Banco Central informou que dados cadastrais de cerca de 160,1 mil clientes da Acesso Soluções de Pagamento foram expostos entre 3 e 5 de dezembro de 2021, sem envolver senhas, saldos ou extratos. Foi o segundo incidente do tipo desde o lançamento do Pix em 2020.', 'Reforça a importância de práticas de segurança e governança de dados em instituições que operam infraestrutura financeira crítica sob a LGPD.', '2022-01-21'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Privacy', 'Regulamentação']::text[], array['Pix', 'Banco Central', 'Vazamento de Dados', 'LGPD']::text[], 'Agência Brasil', 'https://agenciabrasil.ebc.com.br/economia/noticia/2022-01/bc-comunica-vazamento-de-dados-de-1601-mil-chaves-pix', null, false, '{}'::jsonb, 'published'),
  ('power-bi-ignite-2022', 'power-bi-ignite-2022', 'Microsoft leva novidades de BI corporativo ao Power BI no Ignite 2022', 'No Microsoft Ignite 2022, a Microsoft anunciou, em prévia, que relatórios do Power BI poderão ser visualizados e editados diretamente no OneDrive e no SharePoint, sem instalar o Power BI Desktop. A empresa também informou que o Power BI passará a ser instalado automaticamente para usuários do Office, reduzindo a implantação manual pela equipe de TI.', 'Facilita o autoatendimento analítico dentro do ecossistema Microsoft, reduzindo fricção para usuários de negócio que dependem de BI no dia a dia.', '2022-10-12'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-10-29.', array['Business Intelligence']::text[], array['Power BI', 'Microsoft Ignite', 'Self-Service BI', 'OneDrive']::text[], 'Microsoft (Ignite 2022 Book of News)', 'https://news.microsoft.com/ignite-2022-book-of-news/', null, false, '{"trackSlugs":["business-intelligence"]}'::jsonb, 'published'),
  ('google-data-studio-vira-looker-studio', 'google-data-studio-vira-looker-studio', 'Google renomeia o Data Studio para Looker Studio', 'Durante o Google Cloud Next 2022, o Google anunciou que o Data Studio passaria a se chamar Looker Studio, unificando a marca de seus produtos de BI sob o guarda-chuva do Looker, adquirido em 2020. A mudança buscou sinalizar uma trilha única entre a ferramenta gratuita e o Looker corporativo.', 'Reorganiza o portfólio de BI do Google em um momento de forte disputa entre Power BI, Tableau e Looker pelo mercado de análise de negócios self-service.', '2022-10-11'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Business Intelligence']::text[], array['Google', 'Looker Studio', 'Data Studio', 'Rebranding']::text[], 'Google Cloud (blog oficial)', 'https://cloud.google.com/blog/products/data-analytics/looker-studio-is-data-studio', null, false, '{}'::jsonb, 'published'),
  ('apache-kafka-33-kraft-producao', 'apache-kafka-33-kraft-producao', 'Apache Kafka 3.3 marca o modo KRaft como pronto para produção', 'A versão 3.3 do Apache Kafka implementou o KIP-833, declarando o modo KRaft (que dispensa o Apache Zookeeper para gerenciamento de metadados) como pronto para produção em novos clusters. A mudança também trouxe atualizações no Kafka Streams e no Kafka Connect.', 'Simplifica a operação de clusters Kafka ao remover a dependência do Zookeeper, um dos pontos de maior complexidade operacional em arquiteturas de streaming de dados.', '2022-10-03'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Open Source']::text[], array['Apache Kafka', 'KRaft', 'Streaming', 'Zookeeper']::text[], 'Apache Kafka (blog oficial)', 'https://blogsarchive.apache.org/kafka/entry/what-rsquo-s-new-in', null, false, '{}'::jsonb, 'published'),
  ('anpd-regras-simplificadas-2022', 'anpd-regras-simplificadas-2022', 'ANPD aprova regras simplificadas de LGPD para agentes de pequeno porte', 'A Autoridade Nacional de Proteção de Dados publicou a Resolução CD/ANPD nº 2/2022, criando regras simplificadas de conformidade à LGPD para microempresas, startups e pessoas físicas que atuam como agentes de tratamento de dados. O texto dispensa, por exemplo, a obrigatoriedade de encarregado de dados e amplia prazos de resposta a incidentes.', 'Reduz o custo de conformidade com a LGPD para pequenas empresas e startups de dados, um tema recorrente para quem constrói produtos que tratam dados pessoais no Brasil.', '2022-01-27'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Regulamentação', 'Data Governance']::text[], array['LGPD', 'ANPD', 'Startups', 'Regulamentação']::text[], 'ANPD (site oficial)', 'https://www.gov.br/anpd/pt-br/acesso-a-informacao/institucional/atos-normativos/regulamentacoes_anpd/resolucao-cd-anpd-no-2-de-27-de-janeiro-de-2022', null, false, '{}'::jsonb, 'published'),
  ('irlanda-multa-instagram-gdpr', 'irlanda-multa-instagram-gdpr', 'Irlanda multa o Instagram em € 405 milhões por exposição de dados de menores', 'A autoridade irlandesa de proteção de dados (DPC) aplicou uma multa recorde de € 405 milhões ao Instagram por permitir que contas comerciais de adolescentes de 13 a 17 anos exibissem publicamente telefone e e-mail. A investigação, iniciada em 2020, resultou em uma das maiores penalidades já aplicadas sob o GDPR europeu.', 'Mostra o custo real do descumprimento de regras de privacidade para plataformas que lidam com dados de menores, referência direta para quem trabalha com governança e privacidade de dados.', '2022-09-05'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Privacy', 'Regulamentação']::text[], array['Meta', 'Instagram', 'GDPR', 'Irlanda DPC']::text[], 'TechCrunch', 'https://techcrunch.com/2022/09/05/instagram-gdpr-fine-childrens-privacy/', null, false, '{}'::jsonb, 'published'),
  ('uber-invasao-lapsus-2022', 'uber-invasao-lapsus-2022', 'Uber sofre invasão que compromete sistemas internos após ataque de engenharia social', 'Um hacker de 18 anos, ligado ao grupo Lapsus$, obteve acesso administrativo a sistemas internos da Uber, incluindo Slack, AWS, Google Workspace e VMware, após enganar um funcionário via engenharia social. A empresa precisou tirar sistemas internos do ar durante a investigação do incidente.', 'Exemplo emblemático de como falhas de segurança em credenciais e identidade podem expor toda a infraestrutura de dados corporativa, mesmo sem uso de malware sofisticado.', '2022-09-16'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Privacy']::text[], array['Uber', 'Vazamento de Dados', 'Segurança', 'Lapsus$']::text[], 'TechCrunch', 'https://techcrunch.com/2022/09/16/uber-internal-network-hack/', null, false, '{}'::jsonb, 'published'),
  ('databricks-lider-gartner-2022', 'databricks-lider-gartner-2022', 'Databricks é nomeada líder no Magic Quadrant de Bancos de Dados em Nuvem do Gartner', 'O Gartner posicionou a Databricks como líder no Magic Quadrant 2022 para Sistemas de Gerenciamento de Banco de Dados em Nuvem, reconhecendo tanto a capacidade de execução quanto a visão da plataforma de lakehouse. Outros players como AWS, Google e Cloudera também apareceram como líderes no mesmo relatório.', 'Reforça a legitimidade da arquitetura de lakehouse como alternativa consolidada aos data warehouses tradicionais na visão de analistas de mercado.', '2022-12-16'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Mercado', 'Data Platforms']::text[], array['Databricks', 'Gartner', 'Cloud Database', 'Lakehouse']::text[], 'Databricks (blog oficial)', 'https://www.databricks.com/blog/2022/12/16/databricks-named-leader-2022-gartner-magic-quadrant-cloud-database-management', null, false, '{}'::jsonb, 'published'),
  ('mongodb-queryable-encryption-preview', 'mongodb-queryable-encryption-preview', 'MongoDB lança a prévia da Queryable Encryption', 'No MongoDB World 2022, a MongoDB apresentou a prévia da Queryable Encryption, recurso que permite consultar dados totalmente criptografados no lado do cliente sem precisar descriptografá-los no servidor. Inicialmente o recurso suportava consultas de igualdade, com planos de expandir para intervalos e substrings.', 'Abre caminho para aplicações consultarem dados sensíveis criptografados sem expor texto plano ao banco, relevante para times que lidam com dados regulados ou pessoais.', '2022-06-07'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Data Privacy']::text[], array['MongoDB', 'Queryable Encryption', 'Criptografia', 'NoSQL']::text[], 'MongoDB (blog oficial)', 'https://www.mongodb.com/company/blog/product-release-announcements/mongodb-releases-queryable-encryption-preview', null, false, '{}'::jsonb, 'published'),
  ('openai-lanca-gpt-4', 'openai-lanca-gpt-4', 'OpenAI lança o GPT-4, elevando o patamar dos modelos de linguagem multimodais', 'A OpenAI apresentou o GPT-4, seu modelo de linguagem capaz de processar texto e imagens, disponibilizado inicialmente via ChatGPT Plus e por lista de espera na API. O modelo passou a ser usado por empresas como Stripe, Duolingo e Morgan Stanley logo no lançamento.', 'Marcou a virada do mercado de dados e software para a corrida de IA generativa, influenciando diretamente ferramentas de BI, análise e automação lançadas ao longo do ano.', '2023-03-14'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Machine Learning']::text[], array['OpenAI', 'GPT-4', 'LLM', 'Multimodal']::text[], 'TechCrunch', 'https://techcrunch.com/2023/03/14/openai-releases-gpt-4-ai-that-it-claims-is-state-of-the-art/', null, false, '{}'::jsonb, 'published'),
  ('salesforce-einstein-gpt', 'salesforce-einstein-gpt', 'Salesforce lança Einstein GPT, IA generativa integrada ao CRM', 'A Salesforce anunciou o Einstein GPT, combinando modelos próprios com tecnologia da OpenAI para gerar automaticamente e-mails, respostas de atendimento e código a partir de dados de clientes armazenados na plataforma. A empresa também criou um fundo de US$ 250 milhões para investir em startups de IA generativa.', 'Mostra como fornecedores de CRM e analytics passaram a embutir IA generativa diretamente nos fluxos de trabalho de dados corporativos já em 2023.', '2023-03-07'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Business Intelligence']::text[], array['Salesforce', 'Einstein GPT', 'CRM', 'OpenAI']::text[], 'Salesforce (comunicado oficial)', 'https://www.salesforce.com/news/press-releases/2023/03/07/einstein-generative-ai/', null, false, '{}'::jsonb, 'published'),
  ('tableau-einstein-gpt', 'tableau-einstein-gpt', 'Tableau anuncia recursos de IA generativa com Einstein GPT', 'A Salesforce anunciou novas funcionalidades para o Tableau apoiadas em IA generativa, incluindo geração automática de narrativas a partir dos dados (Data Stories), integração com Slack e personalização de dashboards por perfil de usuário.', 'Ilustra a tendência de 2023 de inserir linguagem natural e narrativas automáticas em ferramentas de BI tradicionais, tema central para quem trabalha com Analytics Engineering e dashboards.', '2023-03-15'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Business Intelligence', 'Data Analytics']::text[], array['Tableau', 'Einstein GPT', 'Data Stories', 'BI']::text[], 'Salesforce (comunicado oficial)', 'https://www.salesforce.com/news/stories/tableau-visualization-news-23-1/', null, false, '{"trackSlugs":["business-intelligence"]}'::jsonb, 'published'),
  ('pinecone-serie-b', 'pinecone-serie-b', 'Pinecone capta US$ 100 milhões em rodada Série B para seu banco de dados vetorial', 'A Pinecone anunciou uma rodada Série B de US$ 100 milhões, liderada pela Andreessen Horowitz, avaliando a empresa em US$ 750 milhões. A captação refletiu a demanda crescente por bancos de dados vetoriais para sustentar aplicações de IA generativa com clientes como Shopify e HubSpot.', 'Marca a consolidação dos bancos vetoriais como categoria de infraestrutura essencial para RAG e busca semântica, um dos temas técnicos mais quentes de 2023 em engenharia de dados.', '2023-04-26'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Mercado']::text[], array['Pinecone', 'Vetores', 'Vector Database', 'Funding']::text[], 'Pinecone (blog oficial)', 'https://www.pinecone.io/blog/series-b/', null, false, '{}'::jsonb, 'published'),
  ('microsoft-anuncia-fabric', 'microsoft-anuncia-fabric', 'Microsoft anuncia o Microsoft Fabric, plataforma unificada de dados e analytics', 'Durante o Microsoft Build 2023, a Microsoft apresentou o Fabric, unificando Power BI, Data Factory, Synapse e um data lake compartilhado (OneLake) em uma única plataforma SaaS de análise de dados. Satya Nadella chamou o lançamento de o maior lançamento de produto de dados da empresa desde o SQL Server.', 'Reorganiza o mercado de data warehouse/lakehouse corporativo ao consolidar engenharia de dados, integração e BI em uma superfície única, afetando diretamente quem trabalha com stacks Microsoft/Azure.', '2023-05-23'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Cloud']::text[], array['Microsoft Fabric', 'Power BI', 'Data Lake', 'Synapse']::text[], 'Microsoft Azure (blog oficial)', 'https://azure.microsoft.com/en-us/blog/introducing-microsoft-fabric-data-analytics-for-the-era-of-ai/', null, true, '{}'::jsonb, 'published'),
  ('snowflake-adquire-neeva', 'snowflake-adquire-neeva', 'Snowflake adquire a startup de busca Neeva por cerca de US$ 185 milhões', 'A Snowflake anunciou a aquisição da Neeva, startup de busca fundada por ex-executivos do Google, dias depois de a própria Neeva encerrar seu produto de busca ao consumidor. O objetivo é trazer busca conversacional baseada em IA generativa para dentro da Data Cloud.', 'Exemplifica o movimento de fornecedores de data warehouse comprando tecnologia de IA para tornar a exploração de dados mais acessível a usuários não técnicos.', '2023-05-24'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Platforms', 'Mercado']::text[], array['Snowflake', 'Neeva', 'Busca', 'IA Generativa']::text[], 'Snowflake (blog oficial)', 'https://www.snowflake.com/en/blog/snowflake-acquires-neeva-to-accelerate-search-in-the-data-cloud-through-generative-ai/', null, false, '{}'::jsonb, 'published'),
  ('databricks-compra-mosaicml', 'databricks-compra-mosaicml', 'Databricks compra a MosaicML por US$ 1,3 bilhão para acelerar IA generativa própria', 'A Databricks anunciou a aquisição da MosaicML, criadora dos modelos abertos MPT, por aproximadamente US$ 1,3 bilhão. A combinação visa permitir que empresas treinem e personalizem seus próprios modelos de linguagem usando dados internos, sem depender exclusivamente de fornecedores fechados.', 'Uma das maiores aquisições do ano no setor de dados/IA, consolidando a estratégia de "lakehouse para IA" da Databricks e pressionando concorrentes como Snowflake.', '2023-06-26'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Mercado']::text[], array['Databricks', 'MosaicML', 'LLM', 'Aquisição']::text[], 'Databricks (comunicado oficial)', 'https://www.databricks.com/company/newsroom/press-releases/databricks-signs-definitive-agreement-acquire-mosaicml-leading-generative-ai-platform', null, false, '{}'::jsonb, 'published'),
  ('moveit-vazamento-massivo-2023', 'moveit-vazamento-massivo-2023', 'Ataque em massa explorando falha no MOVEit expõe dados de milhões de pessoas', 'O grupo de ransomware Clop explorou uma vulnerabilidade de injeção SQL no software de transferência de arquivos MOVEit, da Progress Software, comprometendo dados pessoais de mais de 15 milhões de pessoas em dezenas de organizações, incluindo órgãos governamentais dos EUA.', 'Reforça para profissionais de dados a importância de governança e segurança em pipelines de transferência de arquivos, um ponto cego comum em arquiteturas de dados corporativas.', '2023-06-29'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Privacy', 'Infraestrutura']::text[], array['MOVEit', 'Clop', 'Vazamento de Dados', 'Cibersegurança']::text[], 'TechCrunch', 'https://techcrunch.com/2023/06/29/millions-affected-moveit-mass-hacks/', null, false, '{"trackSlugs":["sql"]}'::jsonb, 'published'),
  ('anthropic-lanca-claude-2', 'anthropic-lanca-claude-2', 'Anthropic lança o Claude 2, com janela de contexto de 100 mil tokens', 'A Anthropic lançou o Claude 2, disponível via API e por um novo site público em beta (claude.ai), com melhorias em raciocínio, código e matemática em relação à versão anterior. O modelo passou a suportar janelas de contexto de até 100 mil tokens, bem maiores que as oferecidas pela concorrência na época.', 'Ampliou as opções de LLMs de nível empresarial disponíveis para produtos de dados e análise que dependiam, até então, quase exclusivamente da OpenAI.', '2023-07-11'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial']::text[], array['Anthropic', 'Claude 2', 'LLM', 'Contexto Longo']::text[], 'Anthropic (comunicado oficial)', 'https://www.anthropic.com/news/claude-2', null, false, '{}'::jsonb, 'published'),
  ('meta-lanca-llama-2', 'meta-lanca-llama-2', 'Meta lança o Llama 2 em parceria com a Microsoft, liberando uso comercial', 'A Meta disponibilizou o Llama 2, modelo de linguagem em três tamanhos (7B, 13B e 70B parâmetros), liberado gratuitamente para uso em pesquisa e comercial, em parceria com a Microsoft para distribuição via Azure. O modelo foi treinado com o dobro do volume de dados da primeira versão do Llama.', 'Foi um marco para a IA open source, dando a equipes de dados e engenharia de ML uma alternativa viável a modelos proprietários para treinar e customizar aplicações próprias.', '2023-07-18'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Open Source']::text[], array['Meta', 'Llama 2', 'Open Source', 'Microsoft Azure']::text[], 'Meta AI (blog oficial)', 'https://ai.meta.com/blog/llama-2/', null, false, '{}'::jsonb, 'published'),
  ('snowflake-unifica-iceberg-2023', 'snowflake-unifica-iceberg-2023', 'Snowflake unifica suporte a tabelas Apache Iceberg em sua Data Cloud', 'A Snowflake anunciou a unificação de suas tabelas externas Iceberg e tabelas Iceberg nativas em um único tipo de tabela, permitindo tanto leitura/escrita gerenciadas pela Snowflake quanto interoperabilidade com motores externos do ecossistema Iceberg.', 'Reflete a consolidação do Apache Iceberg como padrão de formato de tabela aberto para arquiteturas lakehouse, tema central de engenharia de dados em 2023.', '2023-08-31'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Data Platforms']::text[], array['Snowflake', 'Apache Iceberg', 'Lakehouse', 'Data Lake']::text[], 'Snowflake (blog oficial)', 'https://www.snowflake.com/en/blog/unifying-iceberg-tables/', null, false, '{}'::jsonb, 'published'),
  ('postgresql-16-lancado', 'postgresql-16-lancado', 'PostgreSQL 16 é lançado com ganhos de performance em paralelismo e replicação', 'O PostgreSQL 16 foi lançado com paralelização de consultas com FULL e RIGHT JOIN, melhorias de até 300% em cargas via COPY e suporte a SIMD em x86 e ARM para acelerar processamento de strings e JSON. A versão também trouxe avanços em replicação lógica e novas opções de controle de acesso.', 'Reforça a posição do PostgreSQL como banco de dados open source de referência, usado como base por diversos serviços gerenciados de nuvem e ferramentas de dados modernas.', '2023-09-14'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Open Source']::text[], array['PostgreSQL', 'SQL', 'Performance', 'Replicação']::text[], 'PostgreSQL Global Development Group (postgresql.org)', 'https://www.postgresql.org/about/news/postgresql-16-released-2715/', null, false, '{"trackSlugs":["sql"],"articleIds":["ctes-recursivas-sql"]}'::jsonb, 'published'),
  ('amazon-bedrock-ga', 'amazon-bedrock-ga', 'Amazon Bedrock chega à disponibilidade geral na AWS', 'A AWS tornou o Amazon Bedrock geralmente disponível, oferecendo acesso via API única a modelos de fundação da Amazon, Anthropic, AI21 Labs, Cohere e Stability AI, com o Llama 2 da Meta chegando em seguida. O serviço também passou a permitir a criação de agentes capazes de executar tarefas de múltiplas etapas.', 'Consolidou a estratégia da AWS de oferecer IA generativa "as a service" multi-modelo, tornando-se peça central de infraestrutura para times de dados que constroem aplicações de IA na nuvem.', '2023-09-28'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Cloud', 'Inteligência Artificial']::text[], array['AWS', 'Amazon Bedrock', 'Foundation Models', 'Anthropic']::text[], 'TechCrunch', 'https://techcrunch.com/2023/09/28/amazon-launches-its-bedrock-generative-ai-service-in-general-availability/', null, false, '{}'::jsonb, 'published'),
  ('anpd-nota-tecnica-pl-ia-2023', 'anpd-nota-tecnica-pl-ia-2023', 'ANPD publica nota técnica sobre o projeto de lei que regula a IA no Brasil', 'A Autoridade Nacional de Proteção de Dados (ANPD) divulgou a Nota Técnica nº 16/2023/CGTP/ANPD, sua segunda análise do PL 2338/2023 (marco legal da IA no Brasil), propondo um novo modelo institucional de fiscalização e apontando sete pontos de interseção e conflito com a LGPD.', 'Mostra o avanço da regulação de IA no Brasil em paralelo à LGPD, tema direto para quem lida com governança e privacidade de dados em produtos que usam IA no país.', '2023-10-24'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Regulamentação', 'Data Governance']::text[], array['ANPD', 'PL 2338/2023', 'LGPD', 'Regulação de IA']::text[], 'FGV Direito - Regulação em Números', 'https://regulacaoemnumeros-direitorio.fgv.br/post/anpd-publica-segunda-analise-do-projeto-de-lei-sobre-inteligencia-artificial', null, false, '{}'::jsonb, 'published'),
  ('nvidia-receita-data-center-2023', 'nvidia-receita-data-center-2023', 'Receita de data center da Nvidia salta 279% impulsionada pela demanda por GPUs de IA', 'A Nvidia reportou receita recorde de US$ 14,51 bilhões em data center no terceiro trimestre fiscal de 2024, alta de 279% em relação ao ano anterior, impulsionada pela demanda por GPUs como a H100 para treinar modelos de IA generativa.', 'Evidencia como a explosão de projetos de IA generativa em 2023 se traduziu diretamente em demanda por infraestrutura de GPU, um gargalo relevante para quem planeja capacidade de treinamento de modelos.', '2023-11-21'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Infraestrutura', 'Mercado']::text[], array['Nvidia', 'H100', 'GPU', 'Data Center']::text[], 'Nvidia (comunicado oficial)', 'https://nvidianews.nvidia.com/news/nvidia-announces-financial-results-for-third-quarter-fiscal-2024', null, false, '{}'::jsonb, 'published'),
  ('mongodb-atlas-vector-search-ga', 'mongodb-atlas-vector-search-ga', 'MongoDB Atlas Vector Search chega à disponibilidade geral', 'A MongoDB anunciou a disponibilidade geral do Atlas Vector Search, permitindo combinar busca vetorial com dados operacionais em uma única API, e do Atlas Search Nodes, que isola workloads de busca para até 60% mais velocidade em consultas.', 'Mostra bancos de dados operacionais tradicionais incorporando capacidades vetoriais nativas, reduzindo a necessidade de manter um banco vetorial separado para aplicações de IA.', '2023-12-04'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Machine Learning']::text[], array['MongoDB', 'Vector Search', 'RAG', 'Busca Semântica']::text[], 'MongoDB (comunicado oficial)', 'https://www.mongodb.com/company/newsroom/press-releases/mongo-db-announces-general-availability-of-new-capabilities-to-power-next-generation-apps', null, false, '{}'::jsonb, 'published'),
  ('23andme-vazamento-2023', '23andme-vazamento-2023', '23andMe confirma que hackers acessaram dados de 6,9 milhões de usuários', 'A empresa de testes genéticos 23andMe confirmou que invasores usaram credenciais reaproveitadas de outros vazamentos (credential stuffing) para acessar contas e, por meio do recurso DNA Relatives, obter dados de parentesco, ancestralidade e localização de cerca de 6,9 milhões de usuários.', 'Caso emblemático de como falhas de autenticação em um pequeno grupo de contas podem expor dados sensíveis de milhões de pessoas conectadas, ponto crítico para quem projeta modelos de dados relacionais/sociais.', '2023-12-04'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Privacy']::text[], array['23andMe', 'Vazamento de Dados', 'Credential Stuffing', 'Dados Genômicos']::text[], 'TechCrunch', 'https://techcrunch.com/2023/12/04/23andme-confirms-hackers-stole-ancestry-data-on-6-9-million-users/', null, false, '{}'::jsonb, 'published'),
  ('google-apresenta-gemini', 'google-apresenta-gemini', 'Google apresenta o Gemini, seu modelo de IA multimodal mais avançado', 'O Google apresentou o Gemini, descrito como seu modelo de IA mais capaz e flexível, construído desde o início para ser multimodal (texto, código, áudio, imagem e vídeo) e disponível em três tamanhos: Ultra, Pro e Nano. A versão Pro passou a alimentar o Bard, enquanto a Nano foi otimizada para dispositivos móveis.', 'Foi a resposta mais direta do Google ao GPT-4 da OpenAI, redefinindo a disputa por modelos de fundação multimodais que sustentam produtos de análise e assistentes de dados.', '2023-12-06'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial']::text[], array['Google', 'Gemini', 'Multimodal', 'Bard']::text[], 'Google (blog oficial)', 'https://blog.google/technology/ai/google-gemini-ai/', null, false, '{}'::jsonb, 'published'),
  ('eu-ai-act-acordo-politico-2023', 'eu-ai-act-acordo-politico-2023', 'União Europeia fecha acordo político sobre o AI Act', 'Após negociações que se estenderam por quase três dias, o Conselho e o Parlamento Europeu chegaram a um acordo político provisório sobre o AI Act, primeira lei abrangente do mundo para regular inteligência artificial por níveis de risco. O texto prevê obrigações de transparência para sistemas de propósito geral e multas de até 7% do faturamento global para infrações graves.', 'Estabeleceu o marco regulatório que hoje molda como empresas de dados e IA precisam documentar, avaliar riscos e reportar o uso de modelos de IA na Europa.', '2023-12-09'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Regulamentação', 'Data Governance']::text[], array['EU AI Act', 'Regulação de IA', 'União Europeia', 'Governança']::text[], 'Conselho da União Europeia (comunicado oficial)', 'https://www.consilium.europa.eu/en/press/press-releases/2023/12/09/artificial-intelligence-act-council-and-parliament-strike-a-deal-on-the-first-worldwide-rules-for-ai/', null, false, '{}'::jsonb, 'published'),
  ('databricks-adquire-tabular', 'databricks-adquire-tabular', 'Databricks anuncia aquisição da Tabular, empresa dos criadores do Apache Iceberg', 'A Databricks anunciou acordo para adquirir a Tabular, startup fundada pelos criadores originais do Apache Iceberg, em um negócio avaliado em mais de US$ 1 bilhão. O objetivo declarado é aproximar os formatos abertos Delta Lake e Iceberg, hoje concorrentes no mercado de lakehouse.', 'Sinaliza a consolidação do Apache Iceberg como padrão de fato para tabelas abertas em data lakes, tema central para quem trabalha com arquitetura de dados moderna.', '2024-06-04'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Data Platforms']::text[], array['Databricks', 'Apache Iceberg', 'Delta Lake', 'Lakehouse', 'Aquisição']::text[], 'Databricks (newsroom oficial)', 'https://www.databricks.com/company/newsroom/press-releases/databricks-agrees-acquire-tabular-company-founded-original-creators', null, true, '{"projectIds":["data-lake-warehouse"],"trackSlugs":["engenharia-de-dados"]}'::jsonb, 'published'),
  ('snowflake-polaris-catalog-open-source', 'snowflake-polaris-catalog-open-source', 'Snowflake torna o Polaris Catalog open source sob licença Apache 2.0', 'A Snowflake liberou o código do Polaris Catalog, seu catálogo de metadados para tabelas Apache Iceberg, sob licença Apache 2.0, permitindo que qualquer empresa hospede seu próprio catálogo sem ficar presa a um fornecedor. O projeto foi doado à Apache Software Foundation.', 'Reduz o lock-in de fornecedores em arquiteturas lakehouse e mostra a disputa entre Snowflake e Databricks pela definição dos padrões abertos do setor.', '2024-07-30'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Open Source']::text[], array['Apache Iceberg', 'Polaris Catalog', 'Snowflake', 'Data Catalog']::text[], 'Snowflake (blog oficial)', 'https://www.snowflake.com/en/blog/polaris-catalog-open-source/', null, false, '{}'::jsonb, 'published'),
  ('eu-ai-act-aprovacao-final-2024', 'eu-ai-act-aprovacao-final-2024', 'Conselho da União Europeia dá aprovação final ao AI Act', 'O Conselho da UE deu o aval final ao AI Act, primeira lei abrangente do mundo para regular inteligência artificial, com regras proporcionais ao risco que um sistema representa. O texto entrou em vigor em agosto de 2024, com obrigações escalonadas nos anos seguintes.', 'Estabelece o primeiro arcabouço regulatório amplo para IA no mundo, com impacto direto em como empresas de dados e IA precisam documentar, avaliar riscos e governar seus modelos.', '2024-05-21'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Regulamentação', 'Data Governance']::text[], array['EU AI Act', 'Regulação', 'União Europeia', 'Governança de IA']::text[], 'Conselho da União Europeia (comunicado oficial)', 'https://www.consilium.europa.eu/en/press/press-releases/2024/05/21/artificial-intelligence-ai-act-council-gives-final-green-light-to-the-first-worldwide-rules-on-ai/', null, false, '{}'::jsonb, 'published'),
  ('aws-s3-tables-iceberg', 'aws-s3-tables-iceberg', 'AWS lança o Amazon S3 Tables, com suporte nativo a Apache Iceberg', 'Durante o AWS re:Invent 2024, a AWS anunciou o Amazon S3 Tables, um novo tipo de bucket otimizado para armazenar tabelas Apache Iceberg com desempenho de consulta até 3x mais rápido. É o primeiro object storage de nuvem com suporte nativo ao formato Iceberg.', 'Mostra a AWS respondendo à adoção maciça do Iceberg, facilitando lakehouses diretamente sobre o S3 sem camadas adicionais de gerenciamento.', '2024-12-03'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Cloud', 'Data Engineering']::text[], array['AWS', 'Apache Iceberg', 'Amazon S3', 're:Invent']::text[], 'AWS (blog oficial)', 'https://aws.amazon.com/about-aws/whats-new/2024/12/amazon-s3-tables-apache-iceberg-tables-analytics-workloads', null, false, '{}'::jsonb, 'published'),
  ('anthropic-claude-3-5-sonnet', 'anthropic-claude-3-5-sonnet', 'Anthropic lança o Claude 3.5 Sonnet', 'A Anthropic lançou o Claude 3.5 Sonnet, modelo que superou o antigo topo de linha Claude 3 Opus em diversos benchmarks, disponibilizado gratuitamente no Claude.ai e no aplicativo iOS, com limites maiores para assinantes Pro e Team.', 'Marca um salto de capacidade em modelos de linguagem usados para análise de dados, geração de código e automação, ampliando o uso prático de IA em fluxos de trabalho de dados.', '2024-06-21'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Machine Learning']::text[], array['Anthropic', 'Claude', 'LLM', 'IA Generativa']::text[], 'Anthropic (blog oficial)', 'https://www.anthropic.com/news/claude-3-5-sonnet', null, false, '{}'::jsonb, 'published'),
  ('duckdb-1-0-estavel', 'duckdb-1-0-estavel', 'DuckDB atinge a versão estável 1.0', 'O projeto DuckDB anunciou a versão 1.0.0, com foco em estabilidade do formato de arquivo, do dialeto SQL e da API C, encerrando o período em que atualizações exigiam migração de arquivos entre versões. O lançamento foi apelidado de "Snow Duck".', 'Consolida o DuckDB como banco analítico embarcado confiável para produção, muito usado em engenharia de dados local e pipelines leves de analytics.', '2024-06-03'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Data Engineering']::text[], array['DuckDB', 'OLAP', 'Open Source', 'Analytics Engineering']::text[], 'DuckDB (blog oficial)', 'https://duckdb.org/2024/06/03/announcing-duckdb-100', null, false, '{}'::jsonb, 'published'),
  ('postgresql-17-lancado', 'postgresql-17-lancado', 'PostgreSQL 17 é lançado com melhorias de performance e memória', 'O PostgreSQL 17 foi lançado com um novo sistema de gerenciamento de memória para o VACUUM, reduzindo consumo de memória e melhorando o desempenho de manutenção do banco, além de outras melhorias de replicação e particionamento.', 'O PostgreSQL segue como base para grande parte da infraestrutura de dados transacionais e analíticos do mercado, incluindo extensões de IA como pgvector.', '2024-09-26'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Open Source']::text[], array['PostgreSQL', 'Banco de Dados', 'Open Source', 'Performance']::text[], 'PostgreSQL Global Development Group (comunicado oficial)', 'https://www.postgresql.org/about/news/postgresql-17-released-2936/', null, false, '{"trackSlugs":["sql"],"articleIds":["ctes-recursivas-sql"]}'::jsonb, 'published'),
  ('meta-lanca-llama-3', 'meta-lanca-llama-3', 'Meta lança o Llama 3, seu modelo de linguagem aberto mais capaz até então', 'A Meta lançou o Llama 3 em versões de 8 bilhões e 70 bilhões de parâmetros, treinado com cerca de 15 trilhões de tokens, disponibilizando os modelos em provedores como AWS, Databricks, Google Cloud e Microsoft Azure.', 'Reforça a corrida por modelos abertos competitivos com os proprietários, ampliando opções para times de dados que querem rodar LLMs com mais controle sobre custo e privacidade.', '2024-04-18'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Machine Learning']::text[], array['Meta', 'Llama 3', 'LLM', 'Open Source']::text[], 'Meta AI (blog oficial)', 'https://ai.meta.com/blog/meta-llama-3/', null, false, '{}'::jsonb, 'published'),
  ('national-public-data-vazamento', 'national-public-data-vazamento', 'National Public Data confirma vazamento com bilhões de registros pessoais', 'A corretora de dados National Public Data confirmou publicamente um vazamento massivo, reconhecendo incidentes em abril e no verão de 2024, associados a um invasor que teria acessado seus sistemas desde dezembro de 2023. Dados como nomes, números de seguro social e endereços foram expostos.', 'Um dos maiores vazamentos de dados pessoais já registrados, ilustrando os riscos de empresas que acumulam grandes volumes de dados sensíveis sem governança adequada.', '2024-08-16'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Privacy', 'Data Governance']::text[], array['Vazamento de Dados', 'National Public Data', 'Privacidade', 'Segurança']::text[], 'BleepingComputer', 'https://www.bleepingcomputer.com/news/security/national-public-data-confirms-breach-exposing-social-security-numbers/', null, false, '{}'::jsonb, 'published'),
  ('openai-gpt-4o', 'openai-gpt-4o', 'OpenAI apresenta o GPT-4o, modelo multimodal em tempo real', 'A OpenAI lançou o GPT-4o ("omni"), capaz de processar texto, áudio e imagem de forma nativa e responder por voz quase em tempo real, disponibilizado gradualmente via API e ChatGPT. Recursos de voz completos chegaram em julho de 2024.', 'Reduz a barreira de latência e custo para aplicações de IA conversacional multimodal, algo relevante para produtos que combinam dados, voz e visão computacional.', '2024-05-13'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Machine Learning']::text[], array['OpenAI', 'GPT-4o', 'Multimodalidade', 'IA Generativa']::text[], 'OpenAI (blog oficial)', 'https://openai.com/index/hello-gpt-4o/', null, false, '{}'::jsonb, 'published'),
  ('nvidia-blackwell-2024', 'nvidia-blackwell-2024', 'Nvidia apresenta a arquitetura de GPUs Blackwell', 'Durante o GTC 2024, a Nvidia revelou a arquitetura Blackwell e os chips B100, B200 e o superchip GB200, prometendo até 4x mais desempenho que a geração Hopper para cargas de treinamento e inferência de IA.', 'Define o próximo patamar de hardware para treinar e servir modelos de IA em escala, impactando diretamente custo e capacidade de infraestrutura de dados/IA das empresas.', '2024-03-18'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Infraestrutura', 'Inteligência Artificial']::text[], array['Nvidia', 'GPU', 'Blackwell', 'Infraestrutura de IA']::text[], 'Nvidia (newsroom oficial)', 'https://nvidianews.nvidia.com/news/nvidia-blackwell-platform-arrives-to-power-a-new-era-of-computing', null, false, '{}'::jsonb, 'published'),
  ('dbt-labs-coalesce-2024', 'dbt-labs-coalesce-2024', 'dbt Labs lança dbt Copilot e suporte a Iceberg na conferência Coalesce 2024', 'Na Coalesce 2024, a dbt Labs anunciou o dbt Copilot (assistente de IA para gerar testes, documentação e modelos semânticos), o dbt Mesh para colaboração entre plataformas de dados distintas, e suporte a tabelas Apache Iceberg em múltiplos engines.', 'Mostra a IA generativa chegando ao dia a dia da engenharia analítica (analytics engineering), automatizando tarefas repetitivas de modelagem e documentação em SQL.', '2024-10-08'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering']::text[], array['dbt Labs', 'dbt Copilot', 'dbt Mesh', 'Apache Iceberg', 'Coalesce']::text[], 'dbt Labs (blog oficial)', 'https://www.getdbt.com/blog/coalesce-2024-product-announcements', null, false, '{}'::jsonb, 'published'),
  ('redis-licenciamento-source-available', 'redis-licenciamento-source-available', 'Redis abandona a licença open source BSD e adota licenciamento "source-available"', 'A partir da versão 7.4, o Redis passou a ser distribuído sob as licenças RSALv2 e SSPLv1, deixando de ser open source segundo a definição da OSI, principalmente para impedir que provedores de nuvem revendam o software como serviço sem contrato comercial. A mudança gerou uma fork da comunidade, o Valkey, sob a Linux Foundation.', 'Reacende o debate sobre sustentabilidade financeira de projetos open source usados em infraestrutura de dados crítica, e força empresas a reavaliar fornecedores e forks.', '2024-03-20'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Open Source']::text[], array['Redis', 'Licenciamento', 'Open Source', 'Valkey']::text[], 'Redis (blog oficial)', 'https://redis.io/blog/redis-adopts-dual-source-available-licensing/', null, false, '{}'::jsonb, 'published'),
  ('databricks-lanca-dbrx', 'databricks-lanca-dbrx', 'Databricks lança o DBRX, modelo de linguagem aberto de mistura de especialistas', 'A Databricks lançou o DBRX, um modelo aberto de 132 bilhões de parâmetros com arquitetura de mistura de especialistas (mixture-of-experts), afirmando superar outros modelos abertos como Llama 2 e Mixtral em benchmarks padrão. O modelo foi desenvolvido pelo time Mosaic Research, herdado da aquisição da MosaicML.', 'Reforça a estratégia da Databricks de oferecer ferramentas de IA generativa integradas à sua plataforma de dados, competindo diretamente com Snowflake nesse espaço.', '2024-03-27'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Machine Learning']::text[], array['Databricks', 'DBRX', 'LLM', 'Open Source', 'Mixture of Experts']::text[], 'Databricks (via PR Newswire)', 'https://www.prnewswire.com/news-releases/databricks-launches-dbrx-a-new-standard-for-efficient-open-source-models-302100601.html', null, false, '{}'::jsonb, 'published'),
  ('gartner-mq-bi-2024', 'gartner-mq-bi-2024', 'Microsoft e Tableau são nomeados líderes no Gartner Magic Quadrant de BI 2024', 'O relatório Gartner Magic Quadrant 2024 para plataformas de Analytics e BI, de 20 de junho, posicionou a Microsoft como líder pelo 17º ano consecutivo, segundo anúncio da própria empresa. A Salesforce informou que o Tableau também foi reconhecido como líder, pelo 12º ano seguido.', 'É a principal referência de mercado que profissionais de BI usam para comparar ferramentas, e reflete a crescente exigência de recursos de IA generativa embutidos em produtos de analytics.', '2024-06-20'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-10-29.', array['Business Intelligence', 'Mercado']::text[], array['Gartner', 'Power BI', 'Tableau', 'Business Intelligence']::text[], 'Microsoft (blog oficial Power BI, cópia arquivada)', 'https://web.archive.org/web/20250115052130/https://powerbi.microsoft.com/en-us/blog/microsoft-named-a-leader-in-the-2024-gartner-magic-quadrant-for-analytics-and-bi-platforms/', null, false, '{"trackSlugs":["business-intelligence"]}'::jsonb, 'published'),
  ('confluent-adquire-warpstream', 'confluent-adquire-warpstream', 'Confluent adquire a WarpStream para expandir streaming de dados "traga sua própria nuvem"', 'A Confluent anunciou a aquisição da WarpStream, startup que reimplementou um serviço compatível com Kafka rodando diretamente sobre object storage, para acelerar sua oferta de streaming de dados no modelo "traga sua própria nuvem" (BYOC).', 'Reflete a tendência de simplificar e baratear infraestrutura de streaming baseada em Kafka, usando armazenamento em nuvem no lugar de discos dedicados.', '2024-09-09'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Big Data']::text[], array['Confluent', 'Apache Kafka', 'WarpStream', 'Streaming', 'BYOC']::text[], 'Confluent (comunicado oficial)', 'https://www.confluent.io/press-release/confluent-acquires-warpstream-to-advance-next-gen-byoc-data-streaming/', null, false, '{}'::jsonb, 'published'),
  ('databricks-serie-j-2024', 'databricks-serie-j-2024', 'Databricks capta US$ 10 bilhões em rodada Série J, atingindo valuation de US$ 62 bilhões', 'A Databricks anunciou uma rodada Série J de até US$ 10 bilhões, liderada pela Thrive Capital, elevando sua avaliação de US$ 43 bilhões (2023) para US$ 62 bilhões, citando crescimento de receita acima de 60% ano a ano impulsionado por IA.', 'Uma das maiores rodadas de venture capital da história, evidenciando o apetite do mercado por plataformas que combinam dados e IA em um único produto.', '2024-12-17'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Mercado', 'Data Platforms']::text[], array['Databricks', 'Investimento', 'Valuation', 'IA']::text[], 'Databricks (newsroom oficial)', 'https://www.databricks.com/company/newsroom/press-releases/databricks-raising-10b-series-j-investment-62b-valuation', null, false, '{}'::jsonb, 'published'),
  ('anpd-suspende-meta-ia-2024', 'anpd-suspende-meta-ia-2024', 'ANPD determina suspensão cautelar do uso de dados pessoais pela Meta para treinar IA', 'A Autoridade Nacional de Proteção de Dados determinou a suspensão imediata, no Brasil, da nova política de privacidade da Meta que permitia usar publicações de usuários para treinar modelos de IA, citando base legal inadequada e falta de transparência.', 'Primeira ação concreta de um órgão regulador de proteção de dados no mundo bloqueando o treinamento de IA generativa com dados de uma rede social, um precedente para a aplicação da LGPD à IA.', '2024-07-02'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Privacy', 'Regulamentação']::text[], array['ANPD', 'LGPD', 'Meta', 'IA Generativa', 'Proteção de Dados']::text[], 'ANPD (comunicado oficial)', 'https://www.gov.br/anpd/pt-br/assuntos/noticias/anpd-determina-suspensao-cautelar-do-tratamento-de-dados-pessoais-para-treinamento-da-ia-da-meta', null, false, '{}'::jsonb, 'published'),
  ('snowflake-vazamento-credenciais-2024', 'snowflake-vazamento-credenciais-2024', 'Vazamento via credenciais roubadas em contas Snowflake atinge AT&T, Ticketmaster e outras empresas', 'Uma campanha de roubo de credenciais (sem exploração de vulnerabilidade na plataforma) permitiu que invasores acessassem contas de clientes da Snowflake que não usavam autenticação multifator, expondo dados da AT&T, Ticketmaster, Santander e outras mais de 160 organizações.', 'Reforça que a segurança de plataformas de dados na nuvem depende fortemente da configuração do cliente (MFA, rotação de credenciais), não só do provedor.', '2024-07-12'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Privacy', 'Bancos de Dados']::text[], array['Snowflake', 'Vazamento de Dados', 'Segurança', 'AT&T', 'Credential Stuffing']::text[], 'CNBC', 'https://www.cnbc.com/2024/07/12/snowflake-shares-slip-after-att-says-hackers-accessed-data.html', null, false, '{}'::jsonb, 'published'),
  ('pgvector-07-lancado', 'pgvector-07-lancado', 'pgvector 0.7 traz novos tipos de vetor e mais desempenho para busca vetorial no Postgres', 'A extensão pgvector 0.7.0 adicionou os tipos halfvec e sparsevec, suporte a índices para vetores binários, novas funções de distância e paralelismo na construção de índices HNSW, melhorando desempenho de busca por similaridade.', 'Mostra o PostgreSQL se consolidando como alternativa viável a bancos vetoriais dedicados para aplicações de busca semântica e RAG (retrieval-augmented generation).', '2024-04-30'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Machine Learning']::text[], array['pgvector', 'PostgreSQL', 'Vector Database', 'RAG']::text[], 'PostgreSQL Global Development Group (comunicado oficial)', 'https://www.postgresql.org/about/news/pgvector-070-released-2852', null, false, '{"trackSlugs":["machine-learning"]}'::jsonb, 'published'),
  ('databricks-serie-l-2025', 'databricks-serie-l-2025', 'Databricks levanta mais de US$ 4 bilhões em rodada Série L e atinge valuation de US$ 134 bilhões', 'A Databricks anunciou uma rodada Série L acima de US$ 4 bilhões, liderada por Insight Partners, Fidelity e J.P. Morgan Asset Management, elevando seu valuation para US$ 134 bilhões. A empresa revelou taxa de receita recorrente acima de US$ 4,8 bilhões e mais de US$ 1 bilhão em receita anualizada só com produtos de IA.', 'Mostra o apetite de investidores por plataformas de dados e IA corporativa, e reforça a posição da Databricks como referência em arquitetura lakehouse.', '2025-12-16'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Mercado', 'Data Platforms']::text[], array['Databricks', 'Funding', 'Lakehouse', 'IA']::text[], 'Databricks (blog oficial)', 'https://www.databricks.com/company/newsroom/press-releases/databricks-surpasses-4-8b-revenue-run-rate-growing-55-year-over-year', null, false, '{}'::jsonb, 'published'),
  ('snowflake-adquire-crunchy-data', 'snowflake-adquire-crunchy-data', 'Snowflake anuncia aquisição da Crunchy Data para levar PostgreSQL enterprise à nuvem de IA', 'Durante o Snowflake Summit 2025, a empresa anunciou a intenção de adquirir a Crunchy Data, fornecedora de tecnologia PostgreSQL open source de nível empresarial. O objetivo é lançar o "Snowflake Postgres", combinando o banco transacional mais popular entre desenvolvedores com a governança e segurança da AI Data Cloud.', 'Sinaliza a aposta das grandes plataformas de dados em bancos operacionais compatíveis com PostgreSQL como base para aplicações de IA e agentes.', '2025-06-02'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Mercado']::text[], array['Snowflake', 'PostgreSQL', 'Aquisição', 'Cloud']::text[], 'Snowflake (blog oficial)', 'https://www.snowflake.com/en/news/press-releases/snowflake-acquires-crunchy-data-to-bring-enterprise-ready-postgres-offering-to-the-ai-data-cloud/', null, false, '{"trackSlugs":["sql"]}'::jsonb, 'published'),
  ('dbt-labs-fusion-engine', 'dbt-labs-fusion-engine', 'dbt Labs lança o motor Fusion, reescrito em Rust, para acelerar o desenvolvimento analítico', 'A dbt Labs apresentou o Fusion, um novo motor construído em Rust com compreensão nativa de SQL, prometendo parsing até 30x mais rápido e orquestração sensível ao estado que executa apenas os modelos alterados. A empresa relata economia média de 10% em custos de computação para clientes early adopters.', 'Redefine a experiência de desenvolvimento em Analytics Engineering, tema central para quem trabalha com dbt e pipelines analíticos modernos.', '2025-05-28'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Data Platforms']::text[], array['dbt', 'Analytics Engineering', 'Rust', 'SQL']::text[], 'PR Newswire / dbt Labs', 'https://www.prnewswire.com/news-releases/dbt-labs-redefines-dbt-with-new-fusion-engine-built-to-revolutionize-developer-experience-in-the-age-of-ai-302466811.html', null, false, '{}'::jsonb, 'published'),
  ('mongodb-adquire-voyage-ai', 'mongodb-adquire-voyage-ai', 'MongoDB adquire a Voyage AI para reforçar busca vetorial e reduzir alucinações de IA', 'A MongoDB anunciou a aquisição da Voyage AI, startup especializada em modelos de embedding e reranking usados por empresas como Anthropic e LangChain. A integração busca oferecer recuperação de informação mais precisa dentro do banco operacional.', 'Reforça a convergência entre bancos de dados operacionais e infraestrutura de busca vetorial/RAG, peça-chave para aplicações de IA generativa confiáveis.', '2025-02-24'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Inteligência Artificial']::text[], array['MongoDB', 'Embeddings', 'RAG', 'Aquisição']::text[], 'PR Newswire / MongoDB', 'https://www.prnewswire.com/news-releases/mongodb-announces-acquisition-of-voyage-ai-to-enable-organizations-to-build-trustworthy-ai-applications-302382979.html', null, false, '{"trackSlugs":["machine-learning"]}'::jsonb, 'published'),
  ('postgresql-18-lancado', 'postgresql-18-lancado', 'PostgreSQL 18 é lançado com novo subsistema de I/O assíncrono e ganhos de até 3x em leitura', 'O PostgreSQL Global Development Group lançou a versão 18, trazendo um subsistema de I/O assíncrono com ganhos de até 3x na leitura de armazenamento, upgrades de versão major menos disruptivos, colunas geradas virtuais e a função uuidv7(). A versão inclui mais de 3.000 commits e suporte a autenticação OAuth.', 'PostgreSQL segue como um dos bancos mais usados no mundo; melhorias de performance e upgrade impactam diretamente times de engenharia de dados e backend.', '2025-09-25'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Open Source']::text[], array['PostgreSQL', 'SQL', 'Performance', 'Open Source']::text[], 'PostgreSQL.org (comunicado oficial)', 'https://www.postgresql.org/about/news/postgresql-18-released-3142/', null, false, '{"trackSlugs":["sql"],"articleIds":["ctes-recursivas-sql"]}'::jsonb, 'published'),
  ('duckdb-142-lts', 'duckdb-142-lts', 'DuckDB lança 1.4.2, segunda atualização da sua primeira versão LTS, com correções de segurança', 'A equipe do DuckDB lançou a versão 1.4.2, corrigindo quatro vulnerabilidades relacionadas à criptografia do banco e ampliando a extensão experimental de Iceberg para suportar operações completas de escrita (insert, update, delete).', 'DuckDB se consolidou como motor analítico embarcado de referência para análise local e integração com lakehouses, tema relevante para quem trabalha com Data Analytics.', '2025-11-12'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Open Source']::text[], array['DuckDB', 'Iceberg', 'Analytics', 'OLAP']::text[], 'DuckDB (blog oficial)', 'https://duckdb.org/2025/11/12/announcing-duckdb-142', null, false, '{}'::jsonb, 'published'),
  ('anthropic-claude-opus-4-5', 'anthropic-claude-opus-4-5', 'Anthropic lança Claude Opus 4.5, seu modelo mais forte em codificação e uso de agentes', 'A Anthropic anunciou o Claude Opus 4.5, alcançando o estado da arte no benchmark SWE-bench Verified e reduzindo em até 76% o uso de tokens em relação a modelos anteriores mantendo desempenho. O lançamento trouxe também Claude Code no aplicativo desktop e compactação de contexto para conversas mais longas.', 'Modelos de raciocínio e agentes como o Opus 4.5 estão sendo cada vez mais usados em automação de pipelines de dados, geração de código analítico e assistentes de engenharia.', '2025-11-24'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Machine Learning']::text[], array['Claude', 'Anthropic', 'AI Agents', 'Coding']::text[], 'Anthropic (blog oficial)', 'https://www.anthropic.com/news/claude-opus-4-5', null, false, '{}'::jsonb, 'published'),
  ('nvidia-rtx-pro-blackwell-servidores', 'nvidia-rtx-pro-blackwell-servidores', 'Nvidia leva GPUs Blackwell para servidores empresariais mainstream com o RTX PRO 6000 Server Edition', 'A Nvidia anunciou que servidores 2U de fabricantes como Dell, HPE, Cisco e Lenovo passarão a oferecer a GPU RTX PRO 6000 Blackwell Server Edition, prometendo até 45x mais performance e 18x mais eficiência energética frente a sistemas apenas com CPU.', 'A disponibilidade de GPUs de ponta em infraestrutura empresarial "mainstream" reduz barreiras para treinar e servir modelos de ML em ambientes corporativos comuns.', '2025-08-11'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Infraestrutura', 'Inteligência Artificial']::text[], array['Nvidia', 'GPU', 'Blackwell', 'Data Center']::text[], 'NVIDIA Newsroom (comunicado oficial)', 'https://nvidianews.nvidia.com/news/nvidia-rtx-pro-servers-with-blackwell-coming-to-worlds-most-popular-enterprise-systems', null, false, '{}'::jsonb, 'published'),
  ('google-gemini-2-5-pro', 'google-gemini-2-5-pro', 'Google lança Gemini 2.5 Pro, seu modelo de "raciocínio" com janela de contexto de 1 milhão de tokens', 'O Google apresentou o Gemini 2.5 Pro Experimental, um modelo que "pensa" antes de responder, liderando o ranking LMArena por margem significativa e atingindo 63,8% no benchmark de codificação SWE-Bench Verified. O modelo chega com janela de contexto de 1 milhão de tokens.', 'Modelos de raciocínio de longo contexto ampliam o que é possível em análise de grandes volumes de documentos e código, um caso de uso direto para times de dados.', '2025-03-25'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Machine Learning']::text[], array['Gemini', 'Google DeepMind', 'LLM', 'Reasoning']::text[], 'Google (blog oficial)', 'https://blog.google/innovation-and-ai/models-and-research/google-deepmind/gemini-model-thinking-updates-march-2025/', null, false, '{}'::jsonb, 'published'),
  ('meta-lanca-llama-4', 'meta-lanca-llama-4', 'Meta lança a família Llama 4 com arquitetura mixture-of-experts e contexto de até 10 milhões de tokens', 'A Meta lançou os modelos Llama 4 Scout e Maverick, disponíveis abertamente via Hugging Face e parceiros. Scout se destaca por caber em uma única GPU H100 com janela de contexto de até 10 milhões de tokens, usando pela primeira vez arquitetura mixture-of-experts na família Llama.', 'Modelos abertos de grande contexto influenciam diretamente arquiteturas de RAG e processamento de bases de dados extensas por equipes que não dependem de APIs fechadas.', '2025-04-05'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Open Source']::text[], array['Meta', 'Llama', 'Open Source', 'Multimodal']::text[], 'Meta AI (blog oficial)', 'https://ai.meta.com/blog/llama-4-multimodal-intelligence/', null, false, '{}'::jsonb, 'published'),
  ('openai-lanca-gpt-5', 'openai-lanca-gpt-5', 'OpenAI lança o GPT-5, unificando raciocínio e respostas rápidas em um único modelo', 'A OpenAI lançou o GPT-5 como modelo padrão para todos os usuários do ChatGPT, combinando a capacidade de raciocínio da série "o" com a velocidade da série GPT. A empresa destacou redução de alucinações (de cerca de 20% para 4,8% em alguns testes) e melhor desempenho em tarefas reais de codificação.', 'Como modelo de uso geral mais adotado do mercado, o GPT-5 influencia diretamente ferramentas de geração de consultas, documentação e automação usadas por equipes de dados.', '2025-08-07'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Machine Learning']::text[], array['OpenAI', 'GPT-5', 'LLM', 'Agentes']::text[], 'TechCrunch', 'https://techcrunch.com/2025/08/07/openais-gpt-5-is-here/', null, false, '{}'::jsonb, 'published'),
  ('gartner-previsao-agentes-ia-2026', 'gartner-previsao-agentes-ia-2026', 'Gartner prevê que 40% dos aplicativos corporativos terão agentes de IA específicos até 2026', 'A Gartner projetou que a proporção de aplicativos corporativos com agentes de IA para tarefas específicas saltará de menos de 5% em 2025 para 40% até o fim de 2026. O relatório também alerta que mais de 40% dos projetos de IA agêntica podem ser cancelados até 2027 por falta de valor claro ou controle de custos.', 'Fornece um contraponto analítico ao hype de agentes de IA, ajudando profissionais de dados a calibrar expectativas de adoção e investimento.', '2025-08-26'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Mercado']::text[], array['AI Agents', 'Gartner', 'Enterprise', 'Previsão']::text[], 'Gartner (comunicado oficial)', 'https://www.gartner.com/en/newsroom/press-releases/2025-08-26-gartner-predicts-40-percent-of-enterprise-apps-will-feature-task-specific-ai-agents-by-2026-up-from-less-than-5-percent-in-2025', null, false, '{}'::jsonb, 'published'),
  ('eu-ai-act-obrigacoes-gpai-2025', 'eu-ai-act-obrigacoes-gpai-2025', 'Últimas obrigações do EU AI Act sobre modelos de IA de uso geral entram em vigor', 'Em 2 de agosto de 2025, entrou em vigor uma nova fase do EU AI Act: o AI Office tornou-se operacional, autoridades nacionais de fiscalização foram designadas e provedores de modelos de IA de uso geral (GPAI) passaram a precisar manter documentação técnica e resumos de dados de treinamento.', 'Times de dados e IA que atuam na Europa (ou vendem para lá) precisam adequar pipelines de treinamento e documentação de modelos a essas novas exigências regulatórias.', '2025-08-07'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Regulamentação', 'Data Governance']::text[], array['EU AI Act', 'Compliance', 'GPAI', 'Europa']::text[], 'DLA Piper', 'https://www.dlapiper.com/en-us/insights/publications/2025/08/latest-wave-of-obligations-under-the-eu-ai-act-take-effect', null, false, '{}'::jsonb, 'published'),
  ('apache-spark-4-0-lancado', 'apache-spark-4-0-lancado', 'Apache Spark 4.0 é lançado com modo ANSI por padrão e novo tipo de dado VARIANT', 'A comunidade Apache Spark lançou a versão 4.0, com mais de 5.100 tickets resolvidos por 390 contribuidores, trazendo modo ANSI SQL ativado por padrão, o novo tipo de dado VARIANT para JSON semiestruturado e um operador PIPE (|>) para encadear transformações SQL.', 'Spark continua sendo o motor de processamento distribuído mais usado em engenharia de dados; a nova versão afeta diretamente pipelines batch e streaming em produção.', '2025-05-28'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Big Data']::text[], array['Apache Spark', 'Open Source', 'ETL', 'PySpark']::text[], 'Databricks (blog oficial)', 'https://www.databricks.com/blog/introducing-apache-spark-40', null, false, '{"trackSlugs":["engenharia-de-dados"]}'::jsonb, 'published'),
  ('microsoft-fabric-fabcon-vienna-2025', 'microsoft-fabric-fabcon-vienna-2025', 'Microsoft Fabric anuncia recursos de Graph e Maps para dar contexto a agentes de IA na FabCon Vienna', 'Na conferência FabCon Vienna, a Microsoft anunciou os recursos Graph (para relações entre entidades de negócio) e Maps (para dados geoespaciais), além de um Fabric MCP para desenvolvimento assistido por agentes e uma nova OneLake Table API para tabelas Iceberg e Delta.', 'Mostra como plataformas de lakehouse corporativo estão se reestruturando para servir como base de dados confiável para agentes de IA, tendência central em 2025.', '2025-09-16'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Data Platforms']::text[], array['Microsoft Fabric', 'OneLake', 'AI Agents', 'Lakehouse']::text[], 'Microsoft Fabric Blog (oficial)', 'https://www.microsoft.com/en-us/microsoft-fabric/blog/2025/09/16/fabcon-vienna-build-data-rich-agents-on-an-enterprise-ready-foundation/', null, false, '{}'::jsonb, 'published'),
  ('deepseek-impacto-nvidia-2025', 'deepseek-impacto-nvidia-2025', 'Ações da Nvidia caem 17% e perdem US$ 600 bilhões em valor de mercado após surpresa da DeepSeek', 'O lançamento do modelo R1 da startup chinesa DeepSeek, que alega desempenho competitivo com muito menos poder computacional, provocou uma queda recorde de 17% nas ações da Nvidia em um único dia, apagando cerca de US$ 600 bilhões em valor de mercado.', 'Foi um dos eventos que mais reconfigurou a narrativa de investimento em infraestrutura de IA em 2025, com efeitos diretos sobre estratégias de hardware para treinamento de modelos.', '2025-01-27'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Mercado']::text[], array['DeepSeek', 'Nvidia', 'China', 'LLM']::text[], 'TechCrunch', 'https://techcrunch.com/2025/01/27/nvidia-drops-600bn-off-its-market-cap-amid-the-rise-of-deepseek/', null, true, '{}'::jsonb, 'published'),
  ('apache-iceberg-1-10', 'apache-iceberg-1-10', 'Apache Iceberg 1.10 amadurece a especificação V3 e o REST Catalog para produção', 'A versão 1.10.0 do Apache Iceberg trouxe compatibilidade total com o Spark 4.0 e o Flink 2.0, além de fechar oficialmente a especificação V3 com deletion vectors para updates eficientes em nível de linha. O Google contribuiu com suporte nativo ao BigQuery Metastore Catalog.', 'Iceberg é hoje o formato de tabela de referência para arquiteturas lakehouse abertas; esse release consolida sua maturidade para cargas de trabalho críticas.', '2025-09-24'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Open Source']::text[], array['Apache Iceberg', 'Lakehouse', 'Data Lake', 'REST Catalog']::text[], 'Google Open Source Blog', 'https://opensource.googleblog.com/2025/09/apache-iceberg-110-maturing-the-v3-spec-the-rest-api-and-google-contributions.html', null, false, '{}'::jsonb, 'published'),
  ('qantas-vazamento-salesforce-2025', 'qantas-vazamento-salesforce-2025', 'Qantas confirma vazamento de dados de 5,7 milhões de clientes após ataque via plataforma Salesforce', 'A companhia aérea australiana Qantas confirmou que invasores obtiveram acesso a dados de 5,7 milhões de clientes através de uma plataforma de terceiros ligada ao Salesforce, usando técnicas de engenharia social contra uma central de atendimento terceirizada.', 'Reforça o risco de integrações com plataformas de CRM/SaaS de terceiros como vetor de vazamento, tema central para quem trabalha com governança e segurança de dados.', '2025-07-09'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Privacy', 'Data Governance']::text[], array['Vazamento de Dados', 'Salesforce', 'Cibersegurança', 'Engenharia Social']::text[], 'Cybersecurity Dive', 'https://www.cybersecuritydive.com/news/qantas-cyberattack-57-million-customers/752571/', null, false, '{}'::jsonb, 'published'),
  ('anpd-mapa-temas-prioritarios-2026-2027', 'anpd-mapa-temas-prioritarios-2026-2027', 'ANPD publica mapa de temas prioritários 2026-2027 e atualiza agenda regulatória da LGPD', 'A Autoridade Nacional de Proteção de Dados (ANPD) publicou, via Resoluções CD/ANPD 30/2025 e 31/2025, o Mapa de Temas Prioritários de fiscalização para 2026-2027 e atualizou a Agenda Regulatória 2025-2026, incluindo novos temas ligados ao ECA Digital, como mecanismos de verificação de idade.', 'Define o roteiro oficial de fiscalização e regulamentação da LGPD para os próximos anos, com impacto direto em como empresas brasileiras devem tratar dados pessoais e de menores.', '2025-12-24'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Regulamentação', 'Data Privacy']::text[], array['LGPD', 'ANPD', 'Brasil', 'Privacidade']::text[], 'ANPD / Gov.br (comunicado oficial)', 'https://www.gov.br/anpd/pt-br/assuntos/noticias/anpd-publica-mapa-de-temas-prioritarios-para-o-bienio-2026-2027-e-atualiza-agenda-regulatoria-2025-2026', null, false, '{}'::jsonb, 'published'),
  ('looker-conversational-analytics-2025', 'looker-conversational-analytics-2025', 'Google amplia Conversational Analytics no Looker, permitindo consultas em linguagem natural com Gemini', 'O Google detalhou o Conversational Analytics no Looker, recurso que permite perguntas em linguagem natural sobre dados modelados em LookML ou tabelas do BigQuery, com respostas rastreáveis via explicação "How was this calculated?". No Google Cloud Next 25, a disponibilidade foi expandida para todos os usuários do Looker.', 'Representa a virada do BI tradicional para experiências conversacionais assistidas por IA, tendência que está redefinindo como analistas e usuários de negócio consultam dados.', '2025-04-29'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Business Intelligence', 'Inteligência Artificial']::text[], array['Looker', 'Gemini', 'BI Conversacional', 'Google Cloud']::text[], 'Google Cloud Blog (oficial)', 'https://cloud.google.com/blog/products/business-intelligence/a-closer-look-at-looker-conversational-analytics/', null, false, '{"trackSlugs":["business-intelligence","data-visualization"]}'::jsonb, 'published'),
  ('anthropic-claude-opus-5', 'anthropic-claude-opus-5', 'Anthropic lança o Claude Opus 5, com desempenho próximo do topo por metade do preço', 'A Anthropic lançou o Claude Opus 5, um modelo posicionado para entregar desempenho próximo ao de seu modelo mais avançado em diversas tarefas, mas a um custo bem menor. É o quarto lançamento da família Claude 5 em menos de dois meses.', 'Mostra a aceleração do ritmo de lançamentos de LLMs em 2026, com foco crescente em custo-benefício além de capacidade bruta — algo direto para quem avalia qual modelo usar em produção.', '2026-07-24'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial', 'Machine Learning']::text[], array['Anthropic', 'Claude', 'LLM', 'Modelos de Linguagem']::text[], 'Axios', 'https://www.axios.com/2026/07/24/anthropic-releases-new-model-opus-5', null, false, '{}'::jsonb, 'published'),
  ('openai-lanca-gpt-6-astra', 'openai-lanca-gpt-6-astra', 'OpenAI lança o GPT-6 (codinome "Astra"), seu modelo mais avançado até agora', 'A OpenAI lançou o GPT-6, internamente chamado "Astra", destacado por forte desempenho em uso de computador/navegador, código e cibersegurança. O lançamento gerou controvérsia por usar "recorrência opaca", uma técnica que dificulta a auditoria do raciocínio do modelo (chain-of-thought).', 'É o primeiro modelo da OpenAI classificado como "crítico" em capacidade cibernética sob seu framework de segurança, tema central para quem trabalha com governança e risco de IA.', '2026-09-03'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Inteligência Artificial']::text[], array['OpenAI', 'GPT-6', 'Agentes de IA', 'Segurança de IA']::text[], 'TechCrunch', 'https://techcrunch.com/2026/09/03/openai-launches-astra-its-powerful-and-controversial-new-model/', null, true, '{}'::jsonb, 'published'),
  ('snowflake-adquire-observe', 'snowflake-adquire-observe', 'Snowflake anuncia aquisição da Observe para observabilidade com IA', 'A Snowflake anunciou acordo definitivo para adquirir a Observe, plataforma de observabilidade com IA que correlaciona logs, métricas e traces usando um "SRE de IA". A operação mira o mercado de gestão de operações de TI, avaliado em mais de US$ 50 bilhões.', 'Sinaliza a expansão das plataformas de dados para observabilidade operacional, um movimento relevante para quem atua com engenharia de dados e infraestrutura de monitoramento.', '2026-01-08'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Platforms', 'Mercado']::text[], array['Snowflake', 'Observabilidade', 'Aquisição', 'Apache Iceberg']::text[], 'Snowflake (comunicado oficial)', 'https://www.snowflake.com/en/news/press-releases/snowflake-announces-intent-to-acquire-observe-to-deliver-ai-powered-observability-at-enterprise-scale/', null, false, '{}'::jsonb, 'published'),
  ('snowflake-adquire-natoma', 'snowflake-adquire-natoma', 'Snowflake anuncia intenção de adquirir a Natoma para gestão de acesso de agentes de IA', 'A Snowflake anunciou a intenção de adquirir a Natoma, plataforma de gateway MCP (Model Context Protocol) que centraliza e controla as permissões de agentes de IA em aplicações corporativas, aplicando políticas de segurança no nível de cada chamada de ferramenta.', 'Reflete a preocupação crescente do mercado com governança de acesso para agentes de IA, um tema emergente essencial para quem projeta arquiteturas de dados seguras para IA agêntica.', '2026-05-27'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Governance', 'Mercado']::text[], array['Snowflake', 'MCP', 'Agentes de IA', 'Governança']::text[], 'Snowflake (comunicado oficial)', 'https://www.snowflake.com/en/blog/snowflake-acquire-natoma-governed-agentic-access/', null, false, '{}'::jsonb, 'published'),
  ('databricks-governance-hub-2026', 'databricks-governance-hub-2026', 'Databricks anuncia Governance Hub e novos recursos de segurança no Data + AI Summit 2026', 'No Data + AI Summit 2026, a Databricks anunciou o Governance Hub (painel centralizado para gestão de postura de governança), além de gestão automática de identidade para Entra ID e Okta, políticas de rede "zero-trust" e novas certificações de compliance (HITRUST, ISMAP, FedRAMP High).', 'Confirma a virada estratégica do setor de "quem constrói o melhor agente" para "quem governa dados, custo e segurança", pauta central para profissionais de governança de dados.', '2026-06-17'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Governance', 'Data Platforms']::text[], array['Databricks', 'Governança', 'Segurança', 'Compliance']::text[], 'Databricks (blog oficial)', 'https://www.databricks.com/blog/whats-new-databricks-platform-security-and-compliance-data-ai-summit-2026', null, false, '{}'::jsonb, 'published'),
  ('microsoft-fabric-iq', 'microsoft-fabric-iq', 'Microsoft apresenta o Fabric IQ, camada semântica para IA empresarial no Fabric', 'A Microsoft detalhou o Fabric IQ, uma camada de inteligência que conecta entidades de negócio, relações e regras em uma ontologia unificada, incluindo o componente Graph (motor de grafo nativo) para permitir que agentes de IA raciocinem sobre dados corporativos conectados.', 'Mostra o movimento das grandes plataformas de dados para camadas semânticas/ontológicas como base para agentes de IA confiáveis, relevante para quem trabalha com modelagem de dados e BI.', '2026-05-06'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Platforms', 'Business Intelligence']::text[], array['Microsoft Fabric', 'Ontologia', 'Grafo', 'IA Empresarial']::text[], 'Microsoft Fabric (blog oficial)', 'https://community.fabric.microsoft.com/blog/fbc_fabricupdatesblogs/from-data-platform-to-intelligence-platform-introducing-microsoft-fabric-iq/5172484', null, false, '{"trackSlugs":["business-intelligence"]}'::jsonb, 'published'),
  ('bigquery-comments-to-sql', 'bigquery-comments-to-sql', 'Google Cloud lança recurso que converte comentários em português/inglês em SQL no BigQuery', 'O Google Cloud lançou o recurso "Comments to SQL" no BigQuery Studio, que transforma instruções em linguagem natural escritas dentro de comentários SQL em consultas executáveis, usando IA para interpretar o contexto do código ao redor.', 'Reduz a barreira de entrada para análise de dados via SQL, tema relevante para analistas iniciantes e times que buscam acelerar o desenvolvimento de queries com IA.', '2026-01-14'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Analytics', 'Business Intelligence']::text[], array['BigQuery', 'Google Cloud', 'SQL', 'Gemini']::text[], 'Google Cloud (blog oficial)', 'https://cloud.google.com/blog/products/data-analytics/vibe-querying-with-comments-to-sql-in-bigquery', null, false, '{"trackSlugs":["sql"]}'::jsonb, 'published'),
  ('fivetran-dbt-labs-fusao', 'fivetran-dbt-labs-fusao', 'Fivetran e dbt Labs concluem fusão para criar infraestrutura de dados para agentes de IA', 'A fusão entre Fivetran e dbt Labs, anunciada em outubro de 2025, foi oficialmente concluída, unindo movimentação e transformação de dados sob uma só empresa que atende mais de 100 mil times de dados. Na ocasião foi lançado o dbt Core 2.0 em alpha, com motor Fusion em Rust.', 'Consolida dois pilares do ecossistema moderno de dados (ingestão e transformação) sob uma mesma empresa, mudança estrutural importante para quem usa ferramentas de analytics engineering.', '2026-06-01'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Mercado']::text[], array['dbt Labs', 'Fivetran', 'Fusão', 'Transformação de Dados']::text[], 'Fivetran (comunicado oficial)', 'https://www.fivetran.com/press/fivetran-dbt-labs-complete-merger-to-create-the-data-infrastructure-for-trusted-ai-agents', null, false, '{}'::jsonb, 'published'),
  ('apache-iceberg-1-11', 'apache-iceberg-1-11', 'Apache Iceberg 1.11.0 é lançado com nova API de formato de arquivo e suporte geoespacial', 'A comunidade Apache Iceberg lançou a versão 1.11.0, resultado de mais de mil commits de 200+ contribuidores, trazendo a finalização da File Format API, criptografia de listas de manifesto, tipos geoespaciais nativos e suporte ao Apache Spark 4.1 e Flink 2.1.', 'O Iceberg é hoje o padrão de fato para tabelas em data lakehouses; essa release amplia recursos críticos de segurança e desempenho usados por engenheiros de dados diariamente.', '2026-05-19'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Engineering', 'Open Source']::text[], array['Apache Iceberg', 'Lakehouse', 'Open Source', 'Apache Spark']::text[], 'Apache Iceberg (blog oficial)', 'https://iceberg.apache.org/blog/apache-iceberg-1.11.0-release/', null, false, '{"trackSlugs":["engenharia-de-dados"]}'::jsonb, 'published'),
  ('apache-polaris-top-level-project', 'apache-polaris-top-level-project', 'Apache Polaris se torna projeto de nível superior da Apache Software Foundation', 'O Apache Polaris, catálogo aberto para tabelas Apache Iceberg originado na Snowflake, graduou-se de projeto incubado para projeto de nível superior (top-level project) da ASF, após 18 meses de incubação com seis releases e cerca de 100 contribuidores.', 'Reforça a maturidade dos catálogos abertos como padrão de interoperabilidade entre motores (Spark, Snowflake, Databricks etc.) em arquiteturas de lakehouse multi-engine.', '2026-02-19'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Open Source', 'Data Engineering']::text[], array['Apache Polaris', 'Catálogo de Dados', 'Iceberg', 'Lakehouse']::text[], 'Apache Polaris (blog oficial)', 'https://polaris.apache.org/blog/2026/02/19/apache-polaris-graduates-to-top-level-project/', null, false, '{}'::jsonb, 'published'),
  ('anpd-multa-tiktok-2026', 'anpd-multa-tiktok-2026', 'ANPD multa TikTok em R$ 153,7 milhões por uso indevido de dados de crianças e adolescentes', 'A Autoridade Nacional de Proteção de Dados (ANPD) aplicou multa de R$ 153,7 milhões à ByteDance, controladora do TikTok, por tratar dados pessoais de menores sem base legal adequada, tanto no feed de usuários logados quanto deslogados, além de exigir a exclusão dos dados coletados irregularmente.', 'É uma das maiores sanções já aplicadas pela ANPD, um marco prático de como a fiscalização da LGPD está se intensificando para quem lida com dados de usuários no Brasil.', '2026-08-25'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Privacy', 'Regulamentação']::text[], array['LGPD', 'ANPD', 'TikTok', 'Proteção de Menores']::text[], 'ANPD (comunicado oficial)', 'https://www.gov.br/anpd/pt-br/assuntos/noticias/anpd-multa-tiktok-em-r-153-7-milhoes-por-falhas-na-protecao-de-dados-de-criancas-e-adolescentes', null, true, '{}'::jsonb, 'published'),
  ('eu-ai-act-fiscalizacao-2026', 'eu-ai-act-fiscalizacao-2026', 'União Europeia começa a fiscalizar o AI Act e exige transparência sobre conteúdo gerado por IA', 'A partir de 2 de agosto de 2026, o AI Office da UE e as autoridades nacionais passaram a ter poder efetivo de fiscalização sobre o AI Act, exigindo que sistemas de IA se identifiquem como automatizados, que deepfakes sejam sinalizados e que conteúdo gerado por IA tenha marcação detectável, sob multas de até 3% do faturamento global.', 'Marca o início real da fiscalização da principal lei de IA do mundo, com impacto direto em qualquer produto que use modelos generativos e opere ou atenda usuários na Europa.', '2026-08-04'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Regulamentação', 'Data Privacy']::text[], array['EU AI Act', 'Regulamentação de IA', 'Transparência', 'União Europeia']::text[], 'Help Net Security', 'https://www.helpnetsecurity.com/2026/08/04/eu-ai-act-enforcement-ai-models/', null, false, '{}'::jsonb, 'published'),
  ('mongodb-search-self-managed', 'mongodb-search-self-managed', 'MongoDB libera Search e Vector Search para implantações auto-gerenciadas', 'A MongoDB anunciou disponibilidade geral de busca textual e busca vetorial para o MongoDB Enterprise Advanced e para o Community Edition (a partir da versão 8.2), permitindo busca híbrida e geração de embeddings automatizada mesmo fora do Atlas, incluindo ambientes on-premises e air-gapped.', 'Elimina a necessidade de ferramentas externas de busca vetorial para quem constrói aplicações de IA/RAG sobre MongoDB fora da nuvem gerenciada, ampliando opções de arquitetura.', '2026-07-01'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Machine Learning']::text[], array['MongoDB', 'Busca Vetorial', 'RAG', 'Self-Managed']::text[], 'MongoDB (blog oficial)', 'https://www.mongodb.com/company/blog/product-release-announcements/mongodb-search-vector-search-now-run-anywhere', null, false, '{}'::jsonb, 'published'),
  ('redis-iris-agentes-ia', 'redis-iris-agentes-ia', 'Redis lança o Iris, motor de contexto e memória para agentes de IA', 'A Redis lançou o Iris, uma plataforma que combina recuperação de contexto em tempo real, memória de curto e longo prazo para agentes e integração de dados, unindo ferramentas como Redis Search, Agent Memory e LangCache em uma única camada voltada a aplicações de IA agêntica.', 'Mostra bancos de dados tradicionais se reposicionando como infraestrutura de memória para agentes de IA, tendência importante para arquitetos de dados que avaliam onde armazenar contexto de IA.', '2026-05-18'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Machine Learning']::text[], array['Redis', 'Agentes de IA', 'Memória', 'Contexto']::text[], 'Redis (blog oficial)', 'https://redis.io/blog/context-is-all-you-need/', null, false, '{}'::jsonb, 'published'),
  ('duckdb-2-0-preview', 'duckdb-2-0-preview', 'DuckDB revela prévia da versão 2.0, com arquitetura cliente-servidor e novo parser SQL', 'O projeto DuckDB divulgou uma prévia da versão 2.0 (codinome "Cyanoptera"), destacando um novo modo cliente-servidor via extensão "quack", suporte a triggers, tipo VARIANT para dados semiestruturados, I/O assíncrono e um novo parser SQL que substitui o herdado do PostgreSQL.', 'O DuckDB se consolidou como ferramenta analítica local/embarcada de referência; a versão 2.0 amplia seu uso para cenários antes exclusivos de bancos cliente-servidor tradicionais.', '2026-08-17'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Bancos de Dados', 'Open Source']::text[], array['DuckDB', 'Banco Analítico', 'Open Source', 'SQL']::text[], 'DuckDB (blog oficial)', 'https://duckdb.org/2026/08/17/duckdb-20-highlights', null, false, '{}'::jsonb, 'published'),
  ('nvidia-vera-rubin-gtc-2026', 'nvidia-vera-rubin-gtc-2026', 'Nvidia detalha plataforma Vera Rubin e novo chip Groq 3 LPU no GTC 2026', 'No keynote do GTC 2026, Jensen Huang formalizou a plataforma Vera Rubin (CPU Vera + GPU Rubin) como supercomputador em rack voltado a IA agêntica, com ganho de eficiência energética 10x sobre a geração Grace Blackwell, além de revelar o novo chip Groq 3 LPU focado em inferência de baixa latência.', 'Define o roadmap de hardware que sustentará cargas de trabalho de IA e processamento de grandes volumes de dados pelos próximos anos, informação-chave para quem planeja infraestrutura de dados/ML.', '2026-03-16'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Infraestrutura', 'Big Data']::text[], array['Nvidia', 'GPU', 'Vera Rubin', 'Infraestrutura de IA']::text[], 'CNBC', 'https://www.cnbc.com/2026/03/16/nvidia-gtc-2026-ceo-jensen-huang-keynote-blackwell-vera-rubin.html', null, false, '{}'::jsonb, 'published'),
  ('databricks-190bi-valuation', 'databricks-190bi-valuation', 'Databricks capta US$ 5 bilhões e atinge valuation de US$ 190 bilhões', 'A Databricks anunciou uma rodada estratégica de captação liderada pela Coatue, elevando sua avaliação para cerca de US$ 188-190 bilhões, apenas cinco meses após uma rodada anterior de US$ 134 bilhões — evidenciando o apetite do mercado por empresas de dados posicionadas em IA.', 'Reflete o quanto o mercado de capital de risco continua priorizando empresas de dados/IA, contexto relevante para entender a saúde financeira do setor em que o profissional de dados atua.', '2026-07-17'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Mercado', 'Data Platforms']::text[], array['Databricks', 'Investimento', 'Valuation', 'IA']::text[], 'TechCrunch', 'https://techcrunch.com/2026/07/17/databricks-hits-188b-valuation-extending-its-run-as-ais-favorite-second-act/', null, false, '{}'::jsonb, 'published'),
  ('pandas-3-0-lancado', 'pandas-3-0-lancado', 'pandas 3.0 é lançado com Copy-on-Write como padrão único e novo dtype de string', 'A biblioteca pandas lançou a versão 3.0, sua primeira grande atualização em anos, tornando o modo Copy-on-Write o único comportamento de cópia de dados (eliminando o antigo aviso SettingWithCopyWarning) e passando a inferir colunas de texto como um novo tipo dedicado "str" em vez de "object".', 'É uma mudança estrutural na ferramenta mais usada por cientistas e analistas de dados em Python, exigindo atenção de quem mantém pipelines e notebooks que dependem do comportamento anterior de cópia de dados.', '2026-01-21'::date, null, 'unverified', 'Importada de content/news. Última conferência da fonte: 2026-09-18.', array['Data Science', 'Open Source']::text[], array['pandas', 'Python', 'Ciência de Dados', 'Breaking Changes']::text[], 'pandas (blog oficial do projeto)', 'https://pandas.pydata.org/community/blog/pandas-3.0.html', null, false, '{"trackSlugs":["ciencia-de-dados"]}'::jsonb, 'published')
