  ('wine-quality', 'Wine Quality', 'Propriedades físico-químicas de vinhos portugueses Vinho Verde (tinto e branco), usadas para prever uma nota de qualidade sensorial.', 'Machine Learning', 'Intermediário', 'cerca de 6.500 registros (tinto + branco)', 'CSV', array['Regressão', 'Classificação', 'Análise exploratória', 'Correlação']::text[], array['Python', 'Pandas', 'Scikit-learn', 'R']::text[], array['Praticar regressão e classificação', 'Explorar correlação entre variáveis']::text[], 'UCI Machine Learning Repository', 'https://archive.ics.uci.edu/dataset/186/wine+quality', 2, 'published'),
  ('california-housing', 'California Housing', 'Dados socioeconômicos e geográficos de distritos da Califórnia, usados para prever o valor médio dos imóveis em cada região.', 'Machine Learning', 'Intermediário', '20.640 registros', 'CSV', array['Regressão', 'Feature engineering', 'Análise exploratória']::text[], array['Python', 'Pandas', 'Scikit-learn']::text[], array['Praticar regressão', 'Estudar feature engineering']::text[], 'scikit-learn', 'https://scikit-learn.org/stable/modules/generated/sklearn.datasets.fetch_california_housing.html', 3, 'published'),
  ('mnist', 'MNIST', 'Base histórica de dígitos manuscritos (0 a 9) em imagens 28x28 em escala de cinza, referência para os primeiros modelos de classificação de imagens.', 'Computer Vision', 'Iniciante', '70.000 imagens (60 mil treino + 10 mil teste)', 'IDX / imagens 28x28', array['Classificação de imagens', 'Redes neurais', 'Deep Learning']::text[], array['Python', 'TensorFlow', 'PyTorch']::text[], array['Primeiro projeto de Deep Learning', 'Introdução a redes neurais']::text[], 'Yann LeCun (NYU)', 'http://yann.lecun.com/exdb/mnist/', 4, 'published'),
  ('fashion-mnist', 'Fashion-MNIST', 'Substituto direto do MNIST com imagens 28x28 de peças de vestuário da Zalando, pensado para ser um benchmark um pouco mais desafiador.', 'Computer Vision', 'Iniciante', '70.000 imagens (60 mil treino + 10 mil teste)', 'IDX / imagens 28x28', array['Classificação', 'Deep Learning', 'Computer Vision']::text[], array['Python', 'TensorFlow', 'PyTorch']::text[], array['Substituir o MNIST em experimentos de Deep Learning', 'Praticar classificação de imagens']::text[], 'Zalando Research (GitHub)', 'https://github.com/zalandoresearch/fashion-mnist', 5, 'published'),
  ('imdb-reviews', 'IMDB Dataset', 'Coleção de avaliações de filmes do IMDB rotuladas como positivas ou negativas, um dos benchmarks mais usados em classificação de texto.', 'NLP', 'Intermediário', '50.000 avaliações rotuladas (+ 50 mil não rotuladas)', 'Texto (.txt)', array['Processamento de linguagem natural', 'Análise de sentimentos', 'Classificação de texto']::text[], array['Python', 'Scikit-learn', 'Hugging Face']::text[], array['Primeiro projeto de NLP', 'Praticar análise de sentimentos']::text[], 'Stanford AI (Andrew Maas et al.)', 'https://ai.stanford.edu/~amaas/data/sentiment/', 6, 'published'),
  ('credit-card-fraud', 'Credit Card Fraud Detection', 'Transações de cartão de crédito de titulares europeus em setembro de 2013, com uma parcela muito pequena marcada como fraude — clássico caso de classe desbalanceada.', 'Machine Learning', 'Avançado', '284.807 transações', 'CSV', array['Detecção de fraude', 'Classificação', 'Análise de dados', 'Classes desbalanceadas']::text[], array['Python', 'Pandas', 'Scikit-learn']::text[], array['Estudar dados desbalanceados', 'Praticar detecção de fraude']::text[], 'Kaggle (ULB Machine Learning Group)', 'https://www.kaggle.com/datasets/mlg-ulb/creditcardfraud', 7, 'published'),
  ('nyc-taxi-trips', 'NYC Taxi Trips', 'Registros oficiais de corridas de táxi de Nova York, com horários, locais de embarque/desembarque e valores — publicados mensalmente desde 2009.', 'Data Analytics', 'Intermediário', 'arquivos mensais com milhões de corridas', 'CSV / Parquet', array['Análise temporal', 'Geolocalização', 'SQL', 'Business Intelligence', 'Visualização de dados']::text[], array['SQL', 'Python', 'Pandas', 'Power BI']::text[], array['Praticar SQL em larga escala', 'Estudar análise temporal e geoespacial']::text[], 'NYC Taxi & Limousine Commission', 'https://www.nyc.gov/site/tlc/about/tlc-trip-record-data.page', 8, 'published'),
  ('superstore', 'Superstore', 'Dataset de vendas de varejo (pedidos, clientes, produtos e regiões) amplamente usado para praticar dashboards e KPIs comerciais.', 'Business Intelligence', 'Iniciante', 'cerca de 10 mil registros de pedidos', 'CSV / XLSX', array['Power BI', 'Dashboards', 'Vendas', 'KPIs', 'Análise comercial']::text[], array['Power BI', 'Tableau', 'Excel', 'SQL']::text[], array['Criar dashboard no Power BI', 'Praticar storytelling com dados de vendas']::text[], 'Kaggle', 'https://www.kaggle.com/datasets/vivek468/superstore-dataset-final', 9, 'published'),
  ('world-happiness-report', 'World Happiness Report', 'Ranking anual de bem-estar de mais de cem países, combinando indicadores econômicos e sociais com uma nota de felicidade autorreportada.', 'Data Analytics', 'Iniciante', 'mais de 140 países, dados anuais desde 2012', 'CSV / XLSX', array['Análise exploratória', 'Estatística', 'Visualização', 'Comparação entre países']::text[], array['Python', 'Pandas', 'Excel']::text[], array['Estudar EDA', 'Comparar indicadores entre países']::text[], 'World Happiness Report', 'https://www.worldhappiness.report/', 10, 'published'),
  ('netflix-titles', 'Netflix Movies and TV Shows', 'Catálogo de filmes e séries do Netflix com gênero, elenco, país, ano de lançamento e classificação, útil para explorar um catálogo de streaming.', 'Data Analytics', 'Iniciante', 'cerca de 8.800 títulos (catálogo até 2021)', 'CSV', array['EDA', 'Visualização', 'SQL', 'Análise de catálogo']::text[], array['SQL', 'Python', 'Pandas', 'Power BI']::text[], array['Praticar EDA', 'Explorar catálogos com SQL']::text[], 'Kaggle', 'https://www.kaggle.com/datasets/shivamb/netflix-shows', 11, 'published'),
  ('spotify-tracks', 'Spotify Tracks', 'Faixas do Spotify com atributos de áudio (dançabilidade, energia, tempo, valência) organizadas por gênero, boas para correlação e visualização.', 'Data Analytics', 'Intermediário', 'mais de 100 mil faixas, 125 gêneros', 'CSV', array['Análise musical', 'Correlação', 'Visualização', 'Estatística']::text[], array['Python', 'Pandas', 'SQL']::text[], array['Explorar correlação entre atributos musicais', 'Praticar visualização de dados']::text[], 'Kaggle', 'https://www.kaggle.com/datasets/maharshipandya/-spotify-tracks-dataset', 12, 'published')
