values
  ('excel-na-pratica', 'Excel na Prática', 'Fundação Bradesco — Escola Virtual', 'Análise de Dados', 'free', 0, 'BRL', null, '16 horas', 'Iniciante', 'Curso gratuito e no seu ritmo para aprender Excel na prática, de fórmulas básicas a tabelas e gráficos.', array['Excel', 'Planilhas', 'Fórmulas']::text[], 'https://www.ev.org.br/cursos/excel-na-pratica', 0, 'published'),
  ('powerbi-intro-bradesco', 'Introdução à Análise de Dados — Microsoft Power BI', 'Fundação Bradesco — Escola Virtual', 'Business Intelligence', 'free', 0, 'BRL', null, null, 'Iniciante', 'Introdução gratuita ao Power BI para transformar dados em relatórios e dashboards.', array['Power BI', 'Dashboards', 'Análise de dados']::text[], 'https://www.ev.org.br/cursos/introducao-a-analise-de-dados-microsoft-power-bi', 1, 'published'),
