  ('ms-learn-transact-sql', 'Introdução ao Transact-SQL', 'Microsoft Learn', 'SQL', 'free', 0, 'BRL', null, null, 'Iniciante', 'Módulo oficial da Microsoft sobre bancos relacionais, a linguagem SQL e o comando SELECT.', array['SQL', 'SELECT', 'Bancos relacionais']::text[], 'https://learn.microsoft.com/pt-br/training/modules/introduction-to-transact-sql/', 6, 'published'),
  ('ms-learn-advanced-tsql', 'Gravar consultas avançadas do Transact-SQL', 'Microsoft Learn', 'SQL', 'free', 0, 'BRL', null, null, 'Intermediário', 'Trilha oficial da Microsoft sobre JOINs, subconsultas, funções de janela e agrupamentos avançados em SQL.', array['JOINs', 'Window Functions', 'Agregações']::text[], 'https://learn.microsoft.com/pt-br/training/paths/write-advanced-transact-sql-queries/', 7, 'published'),
