  ('freecodecamp-relational-database', 'Relational Databases', 'freeCodeCamp', 'SQL', 'free', 0, 'BRL', null, null, 'Iniciante', 'Certificação gratuita da freeCodeCamp com Bash, Git e PostgreSQL, construindo bancos de dados relacionais reais.', array['PostgreSQL', 'Bash', 'Git', 'Modelagem']::text[], 'https://www.freecodecamp.org/learn/relational-databases-v9', 9, 'published'),
  ('kaggle-pandas', 'Pandas', 'Kaggle Learn', 'Ciência de Dados', 'free', 0, 'BRL', null, null, 'Iniciante', 'Curso curto e prático da Kaggle para dominar manipulação de dados com a biblioteca Pandas.', array['Python', 'Pandas', 'Manipulação de dados']::text[], 'https://www.kaggle.com/learn/pandas', 10, 'published'),
