insert into public.projects (id, title, description, area, difficulty, technologies, skills, estimated_time, objective, sort_order, status)
values
  ('analise-vendas-loja', 'Análise de vendas de uma loja', 'Organize os dados de vendas de uma loja para identificar produtos mais vendidos e tendências mensais.', 'Análise de Dados', 'Iniciante', array['Excel', 'Python', 'Pandas']::text[], array['Limpeza de dados', 'Agrupamento', 'Indicadores', 'Análise mensal']::text[], '4–8 horas', 'Praticar limpeza de dados, agrupamento e criação de indicadores para entender o desempenho de vendas de uma loja ao longo do tempo, incluindo a identificação dos produtos mais vendidos.', 0, 'published'),
  ('analise-gastos-pessoais', 'Análise de gastos pessoais', 'Categorize despesas pessoais e monte um dashboard simples para visualizar padrões de consumo.', 'Análise de Dados', 'Iniciante', array['Excel', 'Power BI']::text[], array['Categorização', 'KPIs', 'Dashboard', 'Identificação de padrões']::text[], '3–6 horas', 'Categorizar despesas, criar KPIs financeiros pessoais, identificar padrões de consumo e montar um dashboard simples de acompanhamento.', 1, 'published'),
  ('analise-churn-clientes', 'Análise de churn de clientes', 'Identifique clientes que cancelaram um serviço e investigue os padrões por trás do churn.', 'Análise de Dados', 'Intermediário', array['Python', 'Pandas', 'SQL', 'Power BI']::text[], array['Segmentação', 'Indicadores', 'Insights', 'SQL aplicado']::text[], '8–15 horas', 'Identificar clientes que cancelaram, encontrar padrões de comportamento, criar indicadores de churn e gerar insights acionáveis para retenção.', 2, 'published'),
  ('analise-fraude-transacoes', 'Análise de fraude em transações', 'Explore transações financeiras em busca de padrões suspeitos e construa métricas de monitoramento.', 'Análise de Dados', 'Intermediário', array['Python', 'Pandas', 'SQL', 'Power BI']::text[], array['Análise exploratória', 'Detecção de padrões', 'Métricas', 'Visualização']::text[], '10–16 horas', 'Explorar transações, identificar padrões suspeitos, criar métricas de monitoramento e visualizar o comportamento das operações.', 3, 'published'),
  ('comportamento-clientes-avancado', 'Sistema de análise de comportamento de clientes', 'Construa uma análise completa de comportamento de clientes com segmentação, cohort analysis e métricas de retenção.', 'Análise de Dados', 'Avançado', array['Python', 'SQL', 'Pandas', 'Power BI']::text[], array['Segmentação', 'Cohort analysis', 'Métricas de retenção', 'Dashboard executivo']::text[], '20+ horas', 'Aplicar segmentação de clientes, análise temporal e cohort analysis, calcular métricas de retenção e consolidar os resultados em um dashboard executivo.', 4, 'published'),
  ('previsao-precos-simples', 'Previsão simples de preços', 'Construa um modelo de regressão linear para prever preços a partir de variáveis básicas.', 'Ciência de Dados', 'Iniciante', array['Python', 'Pandas', 'Scikit-learn']::text[], array['EDA', 'Correlação', 'Regressão linear', 'Avaliação de modelo']::text[], '4–8 horas', 'Praticar análise exploratória, correlação, regressão linear e avaliação de um modelo simples de previsão de preços.', 5, 'published'),
  ('previsao-inadimplencia', 'Previsão de inadimplência', 'Treine um modelo de classificação para estimar a probabilidade de inadimplência de clientes.', 'Ciência de Dados', 'Intermediário', array['Python', 'Pandas', 'Scikit-learn']::text[], array['Tratamento de dados', 'Feature engineering', 'Classificação', 'Métricas']::text[], '10–18 horas', 'Tratar os dados, aplicar feature engineering, treinar um modelo de classificação e avaliar seu desempenho com métricas adequadas ao problema.', 6, 'published'),
  ('previsao-demanda', 'Sistema de previsão de demanda', 'Modele séries temporais para prever a demanda futura de um produto ou serviço.', 'Ciência de Dados', 'Avançado', array['Python', 'Pandas', 'Scikit-learn']::text[], array['Séries temporais', 'Feature engineering', 'Modelagem', 'Visualização']::text[], '20+ horas', 'Trabalhar com séries temporais, aplicar feature engineering, modelar a demanda futura, avaliar os resultados e visualizar as previsões geradas.', 7, 'published'),
  ('pipeline-csv-banco', 'Pipeline CSV → Banco de Dados', 'Construa um pipeline simples que lê um CSV, trata os dados e carrega tudo em um banco PostgreSQL.', 'Engenharia de Dados', 'Iniciante', array['Python', 'PostgreSQL']::text[], array['Extração de dados', 'Tratamento de dados', 'Carga em banco de dados']::text[], '4–8 horas', 'Praticar a construção de um fluxo de dados básico: extrair de um CSV, tratar os dados em Python e carregar em um banco relacional.', 8, 'published'),
  ('etl-automatizado', 'Pipeline ETL automatizado', 'Automatize um fluxo de Extract, Transform e Load entre uma fonte de dados e um data warehouse.', 'Engenharia de Dados', 'Intermediário', array['Python', 'SQL', 'PostgreSQL', 'Docker']::text[], array['Extract', 'Transform', 'Load', 'Automação', 'Docker']::text[], '12–20 horas', 'Construir um pipeline ETL automatizado, cobrindo extração, transformação e carga de dados em um ambiente containerizado.', 9, 'published'),
  ('data-lake-warehouse', 'Data Lake + Data Warehouse', 'Desenhe uma arquitetura conceitual conectando fontes de dados, data lake, ETL/ELT e data warehouse até o consumo em BI.', 'Engenharia de Dados', 'Avançado', array['Python', 'SQL', 'Docker']::text[], array['Arquitetura de dados', 'ETL/ELT', 'Modelagem de dados', 'Data Warehouse']::text[], '20+ horas', 'Explorar conceitualmente a arquitetura completa de um pipeline de dados moderno, da ingestão em um data lake ao consumo analítico em ferramentas de BI.', 10, 'published'),
  ('dashboard-vendas', 'Dashboard de vendas', 'Monte um dashboard de vendas com os principais indicadores comerciais de um negócio.', 'Business Intelligence', 'Iniciante', array['Excel', 'Power BI']::text[], array['KPIs', 'Dashboard', 'Storytelling com dados']::text[], '4–8 horas', 'Construir um dashboard com faturamento, ticket médio, quantidade de vendas e margem para acompanhar o desempenho comercial.', 11, 'published'),
  ('dashboard-comercial-completo', 'Dashboard comercial completo', 'Construa um dashboard comercial completo cobrindo vendas, clientes, produtos, regiões e metas.', 'Business Intelligence', 'Intermediário', array['Power BI', 'SQL']::text[], array['Modelagem de dados', 'Comparação temporal', 'Dashboard multiseção']::text[], '10–18 horas', 'Consolidar vendas, clientes, produtos, regiões, metas e comparação temporal em um único painel de análise comercial.', 12, 'published'),
  ('bi-corporativo', 'BI corporativo', 'Simule o BI de uma empresa com múltiplas áreas: comercial, financeiro, marketing e operações.', 'Business Intelligence', 'Avançado', array['Power BI', 'SQL']::text[], array['Arquitetura de indicadores', 'Governança de dados', 'Dashboards multiárea']::text[], '20+ horas', 'Projetar uma arquitetura de indicadores e dashboards que atenda simultaneamente às áreas comercial, financeira, de marketing e de operações.', 13, 'published'),
  ('sql-biblioteca', 'Banco de dados de biblioteca', 'Modele e consulte um banco de dados relacional para o acervo e empréstimos de uma biblioteca.', 'SQL', 'Iniciante', array['SQL', 'PostgreSQL']::text[], array['Modelagem relacional', 'Consultas SQL', 'Chaves primárias e estrangeiras']::text[], '4–8 horas', 'Praticar modelagem relacional básica e consultas SQL para gerenciar livros, usuários e empréstimos.', 14, 'published'),
  ('sql-vendas', 'Banco de dados de vendas', 'Modele um banco de dados de vendas com produtos, clientes e pedidos, e pratique consultas básicas.', 'SQL', 'Iniciante', array['SQL', 'PostgreSQL']::text[], array['Modelagem relacional', 'Consultas SQL', 'Agregações']::text[], '4–8 horas', 'Criar um esquema relacional simples de vendas e praticar consultas de seleção, filtro e agregação.', 15, 'published'),
  ('sql-escola', 'Banco de dados de escola', 'Modele um banco de dados escolar com alunos, turmas e notas, e pratique consultas do dia a dia.', 'SQL', 'Iniciante', array['SQL', 'PostgreSQL']::text[], array['Modelagem relacional', 'Consultas SQL', 'Relacionamentos']::text[], '4–8 horas', 'Praticar modelagem relacional e consultas SQL aplicadas ao contexto de alunos, turmas e avaliações.', 16, 'published'),
  ('sql-ecommerce', 'Sistema de e-commerce', 'Modele o banco de dados de um e-commerce com produtos, pedidos, clientes e pagamentos.', 'SQL', 'Intermediário', array['SQL', 'PostgreSQL']::text[], array['Modelagem relacional', 'JOINs', 'Consultas SQL']::text[], '8–14 horas', 'Modelar um sistema de e-commerce e escrever consultas SQL mais complexas envolvendo múltiplas tabelas relacionadas.', 17, 'published'),
  ('sql-analise-clientes', 'Análise de clientes', 'Escreva consultas SQL para segmentar e analisar o comportamento de clientes a partir de dados transacionais.', 'SQL', 'Intermediário', array['SQL', 'PostgreSQL']::text[], array['JOINs', 'Agregações', 'Segmentação via SQL']::text[], '8–14 horas', 'Usar SQL para segmentar clientes, calcular métricas de comportamento e identificar padrões de consumo.', 18, 'published'),
  ('sql-relatorio-financeiro', 'Relatório financeiro utilizando JOINs e CTEs', 'Construa relatórios financeiros combinando múltiplas tabelas com JOINs e CTEs.', 'SQL', 'Intermediário', array['SQL', 'PostgreSQL']::text[], array['JOINs', 'CTEs', 'Relatórios financeiros']::text[], '8–14 horas', 'Praticar JOINs e CTEs para consolidar dados financeiros de diferentes tabelas em relatórios claros.', 19, 'published'),
  ('sql-data-warehouse-dimensional', 'Data Warehouse dimensional (Star Schema)', 'Modele um data warehouse dimensional usando Star Schema e escreva consultas analíticas otimizadas.', 'SQL', 'Avançado', array['SQL', 'PostgreSQL']::text[], array['Star Schema', 'Modelagem analítica', 'Otimização de queries']::text[], '20+ horas', 'Aplicar modelagem analítica com Star Schema, escrever consultas SQL complexas e praticar otimização de queries em um Data Warehouse dimensional.', 20, 'published'),
  ('ml-classificacao-flores', 'Classificação de flores', 'Treine um modelo de classificação para identificar espécies de flores a partir de suas medidas.', 'Machine Learning', 'Iniciante', array['Python', 'Scikit-learn']::text[], array['Classificação', 'EDA', 'Avaliação de modelo']::text[], '3–6 horas', 'Dar os primeiros passos em classificação supervisionada, do treino do modelo à avaliação dos resultados.', 21, 'published'),
  ('ml-previsao-precos', 'Previsão de preços', 'Treine um modelo de regressão para prever preços a partir de características de um produto ou imóvel.', 'Machine Learning', 'Iniciante', array['Python', 'Scikit-learn']::text[], array['Regressão', 'Preparação de dados', 'Avaliação de modelo']::text[], '4–8 horas', 'Praticar regressão supervisionada, da preparação dos dados à avaliação do modelo treinado.', 22, 'published'),
  ('ml-classificacao-clientes', 'Classificação de clientes', 'Classifique clientes em grupos a partir de características demográficas e comportamentais.', 'Machine Learning', 'Iniciante', array['Python', 'Scikit-learn']::text[], array['Classificação', 'Feature engineering básico']::text[], '4–8 horas', 'Aplicar um modelo de classificação simples para agrupar clientes segundo seu perfil.', 23, 'published'),
  ('ml-deteccao-fraude', 'Detecção de fraude', 'Treine um modelo para identificar transações fraudulentas em uma base com classes desbalanceadas.', 'Machine Learning', 'Intermediário', array['Python', 'Scikit-learn', 'Pandas']::text[], array['Classes desbalanceadas', 'Classificação', 'Métricas de avaliação']::text[], '10–16 horas', 'Lidar com classes desbalanceadas, treinar um classificador de fraude e avaliar métricas além da acurácia.', 24, 'published'),
  ('ml-churn-prediction', 'Churn prediction', 'Construa um modelo preditivo para identificar clientes com alto risco de cancelamento.', 'Machine Learning', 'Intermediário', array['Python', 'Scikit-learn', 'Pandas']::text[], array['Classificação', 'Feature importance', 'Avaliação de modelo']::text[], '10–16 horas', 'Treinar um modelo de classificação para prever churn e interpretar as variáveis mais relevantes para o cancelamento.', 25, 'published'),
  ('ml-recomendacao-simples', 'Sistema de recomendação simples', 'Construa um sistema de recomendação básico usando similaridade entre itens ou usuários.', 'Machine Learning', 'Intermediário', array['Python', 'Scikit-learn', 'Pandas']::text[], array['Similaridade', 'Filtragem colaborativa básica']::text[], '10–16 horas', 'Entender os fundamentos de sistemas de recomendação e implementar uma versão simples baseada em similaridade.', 26, 'published'),
  ('ml-sistema-recomendacao-avancado', 'Sistema de recomendação', 'Evolua um sistema de recomendação mais robusto, combinando diferentes abordagens de recomendação.', 'Machine Learning', 'Avançado', array['Python', 'Scikit-learn', 'Pandas']::text[], array['Recomendação', 'Avaliação de recomendações']::text[], '20+ horas', 'Aprofundar técnicas de recomendação, comparando abordagens e avaliando a qualidade das recomendações geradas.', 27, 'published'),
  ('ml-deteccao-anomalias', 'Detecção de anomalias', 'Identifique comportamentos fora do padrão em um conjunto de dados usando técnicas de detecção de anomalias.', 'Machine Learning', 'Avançado', array['Python', 'Scikit-learn', 'Pandas']::text[], array['Detecção de anomalias', 'Análise exploratória avançada']::text[], '16–24 horas', 'Aplicar técnicas de detecção de anomalias para identificar registros ou comportamentos fora do padrão esperado.', 28, 'published'),
  ('ml-pipeline-completo', 'Pipeline completo de Machine Learning', 'Construa um pipeline de ponta a ponta, da ingestão dos dados ao modelo treinado e avaliado.', 'Machine Learning', 'Avançado', array['Python', 'Scikit-learn', 'Pandas']::text[], array['Pipeline de dados', 'Treinamento de modelo', 'Avaliação']::text[], '20+ horas', 'Estruturar um pipeline completo de Machine Learning, cobrindo ingestão, preparação, treino, avaliação e exportação do modelo.', 29, 'published'),
  ('ml-monitoramento-modelos', 'Monitoramento de modelos', 'Acompanhe o desempenho de um modelo em produção e identifique sinais de degradação ao longo do tempo.', 'Machine Learning', 'Avançado', array['Python', 'Scikit-learn', 'Pandas']::text[], array['Monitoramento', 'Métricas de desempenho', 'Model drift']::text[], '12–20 horas', 'Entender práticas básicas de monitoramento de modelos, acompanhando métricas de desempenho ao longo do tempo.', 30, 'published')
